programs.luna:
"""Flags words about citizenship, civic identity, and public records."""
READS = ()

CIVIC_WORDS = {
    "citizen", "citizens", "nationality",
    "passport", "census", "heritage", "eligibility",
    "ineligible", "parenthood",
}


def step(carry, prefix, upstream):
    """Predict a large response for citizenship labels and a smaller one for related terms."""
    words = prefix.token_strings
    word = words[-1].strip().lower()
    if word == "citizenship":
        return None, -1.95
    if word in CIVIC_WORDS:
        return None, -0.65
    return None, 0.0

programs.haiku:
"""Fires on words that call for a complement saying what is needed or expected:
need/require/must/expect/allow/hope/desire (strong), and 'for' after a noun (weak)."""
READS = ()

NEED_WORDS = {
    "need", "needs", "needed", "required", "requires", "require", "must",
    "desired", "desire", "expect", "expects", "expected", "allow", "allows", "allowed",
    "hoping", "hope", "hopes", "obligatory", "assumes", "assume", "want", "wants",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in NEED_WORDS:
        return carry, 1.5
    if word == "for":
        return carry, 0.4
    return carry, 0.0

programs.luna:
"""Approximate a sparse signal for need, intention, and agency words."""

READS = ()

NECESSITY = {
    "must", "need", "needs", "needed", "require", "requires",
    "required", "requiring", "obligatory", "obligation", "necessary",
    "necessity", "should", "ought",
}

INTENTION = {
    "expect", "expects", "expected", "expecting", "hope", "hoping",
    "desired", "desire", "wants", "want", "interested", "期待",
}

AGENCY = {
    "allow", "allows", "allowed", "enable", "enables", "enabled",
    "force", "forces", "forced", "available", "hired", "hire",
    "disabling", "disable", "raises", "raise", "apply", "applies",
    "assume", "assumes", "estimate", "estimates", "prompt", "prompts",
}

PURPOSE_WORDS = {"for", "to", "upon", "without"}
SHORTAGE_WORDS = {"scarcity", "shortage", "scarce", "lack", "limited"}
MORE_WORDS = {"additional", "further"}
HANDOFF_MARKERS = {"</tool_call>"}


def step(carry, prefix, upstream):
    """Give sparse positive scores to lexical cues for need, plans, and agency."""
    word = prefix.token_strings[-1].lower().strip(
        " \t\r\n.,:;!?()[]{}\"'`"
    )
    if word in NECESSITY:
        return None, 0.9
    if word in INTENTION:
        return None, 0.65
    if word in AGENCY:
        return None, 0.6
    if word in PURPOSE_WORDS:
        return None, 0.35
    if word in SHORTAGE_WORDS:
        return None, 0.65
    if word in MORE_WORDS:
        return None, 0.25
    if word in HANDOFF_MARKERS:
        return None, 0.8
    return None, 0.0

"""A compact approximation to sparse page-navigation and attribution cues.

It recognizes link, share/tag, author, and license phrases, with smaller
baselines for a few common words and the code keyword ``import``. Most text
gets zero; a Markdown heading marker gets a small negative value.
"""

READS = ()

PREPOSITIONS = frozenset({
    "of", "by", "with", "on", "to", "for", "in", "from", "under",
    "over", "into", "after", "before", "through", "against", "without",
    "within", "about", "between", "among", "during", "upon", "per", "via",
})
BYLINES = (
    "originally posted by", "original post by", "last edited by",
    "posted by", "edited by", "powered by", "designed by", "design by",
    "written by", "answer by", "created by",
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    current = prefix.token_strings[-1]
    text = (previous + current)[-120:]
    low = text.lower()
    word = current.strip().lower()
    boundary = current[:1].isspace() or not previous[-1:].isalnum()
    value = 0.0

    # Page links and navigation.
    if boundary and word == "here" and low.endswith(("click here", "clicking here")):
        value = 0.72
    elif boundary and word == "jump" and previous.rstrip().endswith(
        ("<|endoftext|>", "\n")
    ):
        value = 0.25
    elif boundary and word == "to" and low.endswith("jump to"):
        value = 0.42
    elif boundary and word == "navigation" and low.endswith("jump to navigation"):
        value = 0.24
    elif boundary and word == "also" and low.endswith("see also"):
        value = 0.18
    elif boundary and word == "on" and low.endswith("share on"):
        value = 0.52
    elif boundary and word in {"tag", "tags"} and low.endswith(
        ("show tags", "hide tags", "sort by:\ntags", "tags:")
    ):
        value = 0.48

    # Author, forum, and license labels.
    elif boundary and word == "by" and low.endswith(BYLINES):
        value = 0.62
    elif boundary and word == "under" and low.endswith(
        ("licensed under", "license under")
    ):
        value = 0.58
    elif boundary and word in {"edited", "posted"} and low.endswith(
        ("last edited", "originally posted")
    ):
        value = 0.22
    elif boundary and word == "permalink":
        value = 0.55
    elif boundary and word == "profile" and low.endswith("view profile"):
        value = 0.24
    elif boundary and word == "posts" and low.endswith("recommended posts"):
        value = 0.30
    elif boundary and word == "replies":
        value = 0.30
    elif boundary and word == "thread" and low.endswith("exception in thread"):
        value = 0.24
    elif boundary and word == "topic" and low.endswith("old topic"):
        value = 0.28
    elif boundary and word == "message" and low.endswith(
        ("in message", "this message")
    ):
        value = 0.24
    elif boundary and word in {"recent", "recently"} and low.endswith("most " + word):
        value = 0.28
    elif boundary and word == "for" and low.endswith(
        ("sign up for", "signup for", "click here for")
    ):
        value = 0.22

    # Small background estimates for common words and code markers.
    elif boundary and word == "by":
        value = 0.045
    elif boundary and word == "with":
        value = 0.02
    elif boundary and word in {"time", "then"}:
        value = 0.025
    elif boundary and word == "all":
        value = 0.03
    elif boundary and word == "import":
        value = 0.08
    elif boundary and word in PREPOSITIONS:
        value = 0.007
    elif current.strip() == "###":
        value = -0.28

    return (doc, text), float(value)

programs.haiku:
"""Dash-break detector for layer-0 MLP component 6083.

The component turns negative on punctuation dashes that break up English prose:
an aside or afterthought set off after a word ("...the story — just one").
Strength depends on the dash. An em dash fused to the next word ("—the") is the
strongest, then a bare em dash (—), then "--", then spaced en/em dashes and the
ellipsis "…". Hyphens inside words, number ranges, math and code give ~0. It also
goes negative on the word "user" that opens a chat turn (after <|im_start|>).
"""

READS = ()

EM = "—"
EN = "–"
ELLIPSIS = "…"


def _word_before(prefix):
    # True when the token before the current one is a word (letters only).
    return len(prefix.token_strings) > 1 and prefix.token_strings[-2].strip().isalpha()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word_before = _word_before(prefix)
    if tok.startswith(EM) and tok[1:2].isalpha():
        value = -3.2  # em dash fused to the next word, as in "—the"
    elif tok == EM:
        value = -2.3 if word_before else -1.3
    elif tok.strip() == "--":
        value = -1.0 if word_before else 0.0
    elif tok.strip() in (EM, EN, ELLIPSIS):
        value = -0.45 if word_before else -0.15
    elif tok.strip() == "...":
        value = -0.26 if word_before else 0.0
    elif tok == "user" and len(prefix.token_strings) > 1 and prefix.token_strings[-2] == "<|im_start|>":
        value = -0.72
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Recognize sentence dashes and chat speaker labels. An em dash fused to
its following word gets a larger negative prediction than a standalone dash.
"""
READS = ()
DASHES = frozenset("‐‑‒–—―−﹘﹣")
ROLES = {"user": -0.70, "assistant": -0.26, "system": -0.66,
         "developer": -0.66}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    token = tokens[-1]
    visible = token.lstrip()
    if visible.startswith("—") and len(visible) > 1:
        if visible[1].isalpha():
            return None, -4.7
    if visible and visible[0] in DASHES:
        return None, -0.85
    if len(tokens) > 1 and tokens[-2] == "<|im_start|>":
        role = token.strip()
        if role in ROLES:
            return None, ROLES[role]
    return None, 0.0

programs.sol:
"""Predict a token-boundary spelling response, strongest just after H.

Within a word, vowel-starting continuations are negative; consonants,
particularly L/M/N/R, are positive. Fragment length, syllable onset and
common endings adjust this response. Spaces normally suppress it, except
for the reciprocal phrase 'each other'. Related non-Latin letters get
coarser versions of the same rule. This is not a token-ID lookup.
"""
import unicodedata
from functools import lru_cache

READS = ()
VOWELS = frozenset('aeiouyаеёиоуыэюяіїαεηιουω')
CONSONANTS = frozenset(
    'bcdfghjklmnpqrstvwxzбвгджзйклмнпрстфхцчшщβγδζθκλμνξπρστφχψ')
SONORANTS = frozenset('lmnrлмнр')
ENDINGS = frozenset(('s','es','ed','er','ers','ing','ings','ly','en','ens','e'))

@lru_cache(maxsize=20000)
def letters(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))

@lru_cache(maxsize=30000)
def response(previous, token):
    p = letters(previous).strip()
    s = letters(token)
    if token[:1].isspace():
        return -0.97 if p == 'each' and s.strip() == 'other' else 0.0
    if not p or not s:
        return 0.0
    end, first = p[-1], s[0]
    if end == 'h':
        lp, ls = min(len(p), 8), min(len(s), 10)
        second_vowel = len(s) > 1 and s[1] in VOWELS
        vowel_h = len(p) > 1 and p[-2] in VOWELS
        digraph = p.endswith(('th','ph','gh','wh'))
        suffix = s in ENDINGS
        if first in VOWELS:
            return min(0.0, -1.11 + .074*lp + .074*ls + .21*second_vowel
                    - .35*vowel_h + .13*digraph + .24*suffix)
        if first in SONORANTS:
            return max(0.0, 2.17 - .164*lp - .335*ls + .84*second_vowel
                    + .49*vowel_h - .20*digraph - .18*suffix)
        if first in CONSONANTS:
            return max(0.0, 1.11 - .131*lp - .070*ls + .36*second_vowel
                    + .61*vowel_h - .21*digraph + .21*suffix)
        if first.isdigit():
            return -0.10
        return .3 if first in "-/'>" else 0.0
    # Cyrillic fricatives/velars: (vowel, consonant) estimates.
    cyrillic = {'х':(-.84,1.1), 'ш':(-.42,.82), 'ч':(-.42,.42),
                'ж':(-.38,.52), 'г':(-.42,.28), 'щ':(-.21,.20)}
    if end in cyrillic:
        vowel, consonant = cyrillic[end]
        if first in VOWELS:
            return vowel
        if first in CONSONANTS:
            return consonant
    if end in 'θη':
        if first in VOWELS:
            return -.16
        if first in CONSONANTS:
            return .27
    # In Arabic/Persian, heh before vowel letters is especially negative.
    if end == 'ه':
        if first == 'ا':
            return -2.4
        if first in 'یي':
            return -1.4
        if first == 'و':
            return -.7
        if first in 'بپتثجچحخدذرزژسشصضطظعغفقکكگلمنه':
            return .15
    return 0.0

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), response(previous, token)

"""Vietnamese-looking syllables, Latin vowel accents, and regional names.

Most tokens get zero. Selected Vietnamese words and word-initial syllables
get lexical scores even inside other languages. Distinctive Vietnamese
letters in recent text suppress short Latin fragments. Isolated accented
vowels and Latin/Greek letters completed by byte fragments get lexical scores.
Consonant fragments at document starts are negative. Two literal standard-
library fragments also get positive scores. This is a coarse approximation.
"""
import unicodedata as ud
from functools import lru_cache

READS = ()
VOWELS = {
    'â': 1.10, 'ê': .85, 'ô': .98, 'î': .45, 'û': .37,
    'ã': .38, 'õ': .36, 'í': .16, 'ì': .50, 'à': .29,
    'ó': .07, 'ú': .15,
}
SPACE_VOWELS = {
    'â': 1.35, 'ê': .90, 'ô': 1.12, 'î': .90,
    'á': .45, 'í': .30, 'ó': .41, 'ú': .25, 'à': .02,
}
# Vietnamese words which also occur as fragments in other languages.
WORDS = {
    'cho': .85, 'hai': .55, 'mang': .54, 'mong': .85,
    'qua': .90, 'sai': .65, 'ban': .38, 'bang': .35,
    'ca': .17, 'chi': .38, 'ho': .29, 'ta': .28,
    'thu': 1.05, 'sua': .34, 'tin': .60, 'nam': .62,
    'hay': .46, 'sau': .78, 'xe': 1.30,
    'ra': .30, 'tai': .40, 'kim': .25, 'tuy': .35, 'sung': .25,
}
COMPLETE_WORDS = set(
    'các và để sự thể của sẽ rất một bạn này bộ công yêu tìm cùng mình'.split()
)
CONTENT_WORDS = set('kết giá duyệt hơi'.split())
ONSETS = set('ch nh ng kh th tr ph qu gi'.split())
MARKERS = set('đĐơƠưƯ') | {
    chr(c) for c in range(0x1ea0, 0x1efa)
    if c not in (0x1ebc, 0x1ebd)
}


@lru_cache(maxsize=32768)
def lexical(text):
    word = text.strip()
    low = word.lower()
    space = text.startswith(' ')
    marked = any(c in MARKERS for c in word)
    if low in ('vietnam', '越南', 'вьетнам'):
        return 1.45, 0.0, marked
    if low == 'vietnamese':
        return 1.05, 0.0, marked
    if low == 'nam' and (space or word[0].isupper()):
        return .62, (0.0 if word[0].isupper() else -1.10), marked
    if word in ('Gi', 'Thu'):
        return (.43 if word == 'Gi' else .60), -1.35, marked
    if word in ('Đ', 'đ'):
        return (1.45 if word == 'Đ' else .85), -1.20, marked
    if low in ('viet', 'việt'):
        return (.95 if word[0].isupper() else .45), 0.0, marked
    if low in ('thai', 'thailand', 'cambodia', 'cambodian', 'laos'):
        score = .80 if low.startswith('cambod') else .55
        slope = -1.75 if low == 'thai' and word.islower() else 0.0
        return score, slope, marked
    # A C++ standard header and a qualified Java collection class.
    if word in ('/stdc', '.ArrayList'):
        return .75, 0.0, marked
    if word == 'xe':
        return .37, -1.10, marked
    if word == 'โ':
        return .65, 0.0, marked
    if space and low in CONTENT_WORDS:
        return .55, 0.0, marked
    if space and low in COMPLETE_WORDS:
        return .30, 0.0, marked
    nfd = ud.normalize('NFD', low)
    plain = ''.join(c for c in nfd if not ud.combining(c))
    latin = (bool(plain) and len(word) <= 5
             and all(c in 'abcdefghijklmnopqrstuvwxyzđ' for c in plain))
    if not latin:
        return 0.0, 0.0, marked
    base = 0.0
    slope = -.25 if marked else -.40
    if len(word) == 1:
        base = (SPACE_VOWELS if space else VOWELS).get(low, 0.0)
        slope = -1.30 if base > .1 else -.50
    elif low in ONSETS:
        base = .20 if space and low in ('qu', 'tr', 'gi', 'nh') else 0.0
        slope = -1.25 if space else -.65
    elif space and word in WORDS:
        base = WORDS[word]
        slope = -.95 if word == 'ca' else -1.45
    elif space and len(word) <= 3 and len(plain) == 2:
        consonant, vowel = low[0], low[-1]
        if consonant in 'bcdfghjklmnpqrstvxz':
            if vowel in 'âêôîû':
                base = .5 + .6 * VOWELS[vowel]
                base += .5 if consonant in 'cmh' else .1
            elif vowel in 'áéíóú':
                if consonant == 'c':
                    base = 1.80 if vowel == 'ó' else 1.30
                else:
                    base = .80 if consonant in 'bl' else .35
            elif low == 'là':
                base = 1.80
            elif low == 'mã':
                base = 1.35
            slope = -1.70 if base else -.40
    if plain in ('au', 'inh', 'ung', 'ong', 'anh'):
        slope = -1.20
    elif (word not in WORDS and word != 'the' and len(plain) == 3
          and plain[:2] in ONSETS and plain[-1] in 'aeiouy'):
        slope = -.95
    elif plain[0] in 'aeiouy' and len(word) > 1:
        slope -= .25
        if not space and ud.normalize('NFD', low) != low:
            slope -= .30
    return base, slope, marked


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    evidence = 0.0 if new_document else carry[1]
    text = prefix.token_strings[-1]
    base, slope, marked = lexical(text)
    value = base + min(evidence, 1.0) * slope
    if new_document and text.strip().lower() in ONSETS | {'đ'}:
        value = -.35
    evidence = .9 * evidence + float(marked)
    # Individually decoded continuation bytes can finish an accented letter.
    if '�' in text:
        char = prefix.text_prefixes[-1][-1:]
        name = ud.name(char, '')
        if char != '�' and 'LATIN' in name and char.isupper():
            value = .75
            if 'CIRCUMFLEX' in name or 'DIAERESIS' in name:
                value = 1.20
        elif ('LATIN' in name and char not in MARKERS
              and ud.normalize('NFD', char) != char):
            value = 1.10 if 'DIAERESIS' in name else .35
        elif char in 'άέ':
            value = .55
        elif 'GREEK' in name and 'WITH' in name:
            value = .20
    return (doc, evidence), float(value)

"""Console output and its surrounding code syntax, usually a negative response.

Recognizes standard output APIs, C++ stream insertion, Java declarations and
string-opening punctuation. Adjacent words disambiguate overloaded spellings
such as console.log, public class and static void. Spaces and tabs attached to
a token adjust its strength. Everything else is approximated by zero; this
omits the component's weaker, idiosyncratic lexical responses. Only the
previous token is remembered, and that history resets at document boundaries.
"""
READS = ()

# Familiar printing, formatting, logging and console-input methods.
METHODS = {
    '.WriteLine': -4.2,
    '.Println': -2.8,
    '.Sprintf': -2.7,
    '.Errorf': -1.05,
    '.Logf': -1.8,
    '.printf': -2.8,
    '.ReadLine': -1.8,
    '.Print': -1.4,
    '.Format': -1.3,
    '.format': -1.0,
    '.info': -0.6,
    '.error': -0.55,
    '.printStackTrace': -1.25,
    '.stdout': -1.0,
    '.stderr': -0.3,
    '.makeText': -2.2,
}
# Common I/O functions and C-family namespace/header names.
WORDS = {
    'printf': -3.3,
    'fprintf': -2.1,
    'scanf': -1.6,
    'sprintf': -0.75,
    'perror': -0.4,
    'puts': -0.4,
    'print': -0.4,
    'echo': -0.6,
    'println': -1.6,
    'fmt': -0.8,
    'System': -0.65,
    'Console': -1.3,
    'console': -0.4,
    'namespace': -0.6,
    '#include': -0.55,
    'iostream': -1.2,
    'stdio': -1.0,
}
MODIFIERS = {'public', 'private', 'protected', 'static', 'abstract',
             'final', 'partial', 'override', 'virtual', 'inline'}
PRINT_CALLS = {'printf', 'fprintf', 'scanf', 'sscanf', '.printf',
               '.Printf', '.println',
               '.Println', '.print', '.WriteLine', '.Sprintf'}


def response(s, previous):
    w, p = s.strip(), previous.strip()
    if w in {'.out', '.in'}:
        if p.lstrip('(.') != 'System':
            return -0.6 if w == '.out' else 0.0
        if w == '.in':
            return -5.3
        if previous.startswith('\t'):
            return -6.8
        return -6.5 if previous.startswith(' ') else -5.5
    if w == '.Printf':
        return -4.8 if p == 'fmt' else -2.1
    if w in {'.println', '.print'}:
        if p == '.out':
            return -3.8 if w == '.print' else -3.45
        return -3.0 if p == '.err' else -1.2
    if w == '.log':
        return (-2.4 if previous.startswith(' ') else -2.9) if p == 'console' else -0.2
    if w == '.Write':
        return -3.6 if p == 'Console' else -0.5
    if w == '.Show':
        return -3.1 if p == 'MessageBox' else -0.2
    if w == '.class':
        return -1.0
    if w == 'toString':
        return -3.2 if p == 'String' else -0.5
    if w in {'(stderr', '(stdout'}:
        return -2.0
    if w in METHODS:
        return METHODS[w]
    # C++ stream expressions.
    if w == 'cout':
        return -4.5 if p == '::' else -1.8 if p and p[-1].isalpha() else -3.8
    if w.startswith('<<'):
        if p in {'cout', 'cerr'}:
            if w != '<<':
                return -5.0
            if previous.startswith('\t'):
                return -7.0
            return -6.5 if previous.startswith(' ') else -5.5
        return -2.8 if p.endswith(('"', ')', ']')) else -2.1
    if w == 'endl':
        return -3.0 if s.startswith(' ') or '<<' in p else -2.5
    if w == '>>':
        return -3.5 if p == 'cin' else -0.3
    if w == 'cin':
        return -0.7 if p == '::' or previous.isspace() else -0.2
    if w == 'std':
        return -2.4 if p == 'namespace' else -1.1 if p == '<<' else -0.5
    if w == '::':
        return -0.9 if p == 'std' else -0.55 if p == 'fmt' else 0.0
    # Java/C-family declarations and the main entry point.
    if w == 'class':
        if p == 'public':
            return -4.4 if previous == 'public' else -3.6
        return -2.0 if p in MODIFIERS else -0.15
    if w == 'void':
        if p == 'static':
            return -2.7 if previous.startswith(' ') else -1.2
        return -1.5 if p in {'public', 'private'} else -0.6 if p in MODIFIERS else -0.3
    if w == 'main':
        if p == 'void':
            return -3.5
        if p == 'int':
            return -1.3
        return -1.0 if p in {'func', 'fn'} else -0.15
    if w == 'args':
        return -4.8 if p in {'[]', '(String'} else -0.75
    if w in WORDS:
        return -4.1 if w == 'printf' and s.startswith('\t') else WORDS[w]

    # String literals: quotes merged with a call-opening parenthesis, or
    # preceded by whitespace. Escaped quotes alone have a small positive bias.
    if s.strip() in {chr(92) + '"', chr(92) * 2 + '"'}:
        return 0.12
    if s in {'"', "'"} and p == '(f':
        return -0.7
    if s.startswith('!("'):
        return -1.6
    if s.startswith(('("', "('")):
        double = s.startswith('("')
        if p in PRINT_CALLS:
            if p in {'printf', 'fprintf', 'scanf', 'sscanf', '.printf'}:
                return -3.0 if '%' in s else -2.4
            return -1.95 if double else -0.7
        if p in {'print', 'echo', '.log', '.info'}:
            return -1.1 if double else -0.7
        if '%' in s:
            return -1.7
        return -0.5 if double else -0.1
    if s == '(f':
        return -0.2
    if s.startswith((' "', " '")) and not any(c.isalnum() or c == '/' for c in w):
        double = s.startswith(' "')
        if p == '<<':
            return -2.7 if double else -0.55
        if p == '#include':
            return -0.65
        if p in {'\":', '\",'}:
            return -0.3 if double else -0.1
        if p in {'echo', 'print', 'printf', 'puts', '('}:
            return -1.3 if double else -0.55
        if p in {'+', '+='}:
            return -1.05 if double else -0.8
        if p == '=':
            return -0.45 if double else -0.2
        return -0.22 if double else -0.1
    return 0.0


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    return (doc, s), float(response(s, prev))

