"""Console output in code: the print statements of C++, Java, C#, C and Go.

The component goes negative on the tokens of a print call. Strongest: the operator in
`cout << ...` and the `.out` of `System.out.println`. Also `cout` itself, the method of a
print call on a console object (`.println`, `.WriteLine`, `.Printf`, `.log`), and
printf-style calls (printf, fprintf, scanf, endl). Weaker, but frequent, responses: the
text right after an output operator, the string argument of a print call, an opening
string quote, the `args` of a Java main method, and the `public class` / `public void`
keywords of a Java header. Everywhere else it is near zero.
"""
READS = ()

CONSOLE_OBJECTS = {"System", "Console", "console", "fmt", "out"}
PRINT_METHODS = {"println", "Println", "print", "Print", "WriteLine", "Write", "log"}
PRINT_FUNCS = {"printf", "fprintf", "Printf", "Sprintf", "sprintf", "println", "Println",
               "WriteLine", "perror", "scanf", "endl"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]                      # the token as written, e.g. " \"" or ".out"
    cur = tok.strip()                   # the same with spaces removed
    prev = toks[-2].strip() if len(toks) > 1 else ""
    name = cur.lstrip(".")              # the bare word: "out", "println"
    obj = prev.lstrip("(.")             # the bare word before it: "System", "out"
    dotted = tok.startswith(".")
    if cur == "<<" and prev == "cout":
        return None, -6.5               # cout << : the operator right after cout
    if dotted and name == "out" and obj == "System":
        return None, -6.0               # System.out
    if cur == "cout":
        return None, -3.7
    if cur in ("<<", '<<"'):
        return None, -2.0
    if cur == ">>":
        return None, -1.0
    if dotted and name in PRINT_METHODS and obj in CONSOLE_OBJECTS:
        return None, -2.5               # System.out.println, Console.WriteLine, console.log
    if name in PRINT_FUNCS:
        return None, -3.5               # printf(...), .Printf, .WriteLine, endl
    if tok == ' "' and prev in ("<<", ">>"):
        return None, -3.0              # the text printed by cout <<
    if tok.startswith(('("', "('")) and (prev in PRINT_FUNCS or obj in PRINT_METHODS):
        return None, -2.0              # the format string of a print call
    if tok == ' "' and prev == "echo":
        return None, -1.3
    if tok == '("':
        return None, -0.75              # other string arguments
    if tok in (' "', " ('"):
        return None, -0.3               # opening quotes in code
    if cur in ("System", "Console", "std") and tok.startswith(" "):
        return None, -0.7               # the namespace or class a print call sits in
    if cur == "args" and prev.endswith("[]"):
        return None, -4.0              # main(String[] args)
    if cur == "class" and prev == "public":
        return None, -4.2
    if cur == "void" and prev in ("public", "static"):
        return None, -1.5
    return None, 0.0

