"""Recognize a few familiar ways source code writes output.

This component is usually quiet, but becomes strongly negative around
source-code output statements and a few nearby declarations. A smaller
positive response marks a few words of existence, likelihood, and belonging.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    previous = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    # Common output syntax in several programming languages.
    if "<<" in token and "cout" in previous:
        return None, -6.0
    if word == "cout":
        return None, -3.9
    if word == ".out" and previous == "System":
        return None, -6.0
    if word in {".Println", ".Printf", ".Print"} and previous == "fmt":
        return None, -4.5
    if word == ".println" and previous == ".out":
        return None, -3.0
    if word == ".log" and previous.lower() == "console":
        return None, -2.7
    if word.lower() == "printf":
        return None, -2.8
    if word == "fmt":
        return None, -0.8
    if word.lower() == "console":
        return None, -0.5
    if word == "endl" and "<<" in previous:
        return None, -2.9

    # A weaker, less language-specific cue from the name of an output command.
    if word.lower() in {"print", "println", "echo"}:
        return None, -0.5

    # Nearby Java-style declarations and command-line argument lists.
    if word.lower() == "class" and previous.lower() in {
        "public", "private", "protected", "static"
    }:
        return None, -3.6
    if word.lower() == "void" and previous.lower() in {
        "public", "private", "protected", "static"
    }:
        return None, -2.0
    if word == "args" and "]" in previous:
        return None, -5.0
    if word.lower() == "main" and previous.lower() == "void":
        return None, -3.7
    if word.lower() == "main" and previous.lower() in {"func", "int"}:
        return None, -1.0

    # A small positive response to ordinary existence and likelihood words.
    if word.lower() in {"exist", "exists", "existing"}:
        return None, 0.4
    if word.lower() == "likely":
        return None, 0.2
    if word.lower() == "to" and previous.lower() in {"belong", "belongs"}:
        return None, 0.6

    return None, 0.0

