"""Detect spelled-out plural quantities, rather than numeric digits.

Small English cardinals have the strongest negative response. Teens, tens,
vague counts, and selected count words in other languages are weaker.
Capitalization and a few grammatical quantity phrases adjust the response;
'of' continues 'couple of'/'pair of'. Ordinary tokens predict zero.
This is a lexical approximation, not a parser of arbitrary number expressions.
"""
READS = ()

SMALL_COUNTS = {
    'two': -2.27, 'three': -2.04, 'four': -2.02, 'five': -1.95,
    'six': -2.14, 'seven': -2.15, 'eight': -1.85, 'nine': -2.00,
}
EARLY_TEENS = set('eleven twelve thirteen'.split())
TEENS = set('fourteen fifteen sixteen seventeen eighteen nineteen'.split())
ROUND_TENS = set('thirty forty fifty sixty seventy eighty ninety'.split())
QUANTITIES = {
    'ten': -1.19, 'twenty': -0.86,
    'few': -0.95, 'several': -1.35,
    'duo': -0.87, 'twice': -0.81,
    'multiple': -0.49, 'numerous': -0.32, 'many': -0.20,
    'twin': -0.71, 'twins': -0.45, 'dual': -0.39,
    'dozen': -0.77, 'dozens': -0.60, 'handful': -0.60,
    'fewer': -0.27, 'bunch': -0.28,
}
FOREIGN_COUNTS = {
    'deux': -1.50, 'trois': -1.50, 'quatre': -1.07,
    'plusieurs': -0.73, 'zwei': -1.82, 'drei': -1.38,
    'vier': -1.20, 'fünf': -1.27, 'beiden': -0.88,
    'dos': -0.50, 'tres': -0.92, 'cuatro': -1.38,
    'cinco': -1.44, 'seis': -0.89,
    'dois': -1.21, 'duas': -1.28, 'três': -1.34,
    'два': -1.65, 'две': -1.35, 'три': -1.02,
    'двух': -1.36, 'трех': -0.86, 'четыре': -1.77,
    'семь': -0.77, 'несколько': -0.76, '두': -1.23,
    '两': -1.25, '兩': -1.50, '两个': -1.47, '兩個': -1.35,
    '三个': -1.02, '四个': -1.04, '十个': -0.74,
    '两张': -0.95, '两人': -0.93, '两只': -1.40,
    '两种': -1.06, '这两个': -0.78, '几个': -0.77,
    '有两个': -2.01,
}


def lexical_value(word):
    if word in SMALL_COUNTS:
        return SMALL_COUNTS[word]
    if word in EARLY_TEENS:
        return -1.50
    if word in TEENS:
        return -1.32
    if word in ROUND_TENS:
        return -0.70
    return QUANTITIES.get(word, FOREIGN_COUNTS.get(word, 0.0))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    bare = token.strip().lstrip('_-.')
    word = bare.lower()
    value = lexical_value(word)

    if word in SMALL_COUNTS:
        if bare.istitle():
            value -= 0.32
        if previous in ('a', 'an', 'another', 'next'):
            value -= 0.24
        elif previous in ('these', 'those', 'between'):
            value += 0.35
        elif previous == 'exactly':
            value += 0.65
        elif previous in ('all', 'or'):
            value += 0.22
    elif word == 'many':
        if previous == 'how':
            value = -0.69
        elif previous in ('too', 'so'):
            value = -0.47
        elif previous == 'as':
            value = -0.37
        elif previous == 'in':
            value = -0.10
        elif bare.istitle():
            value = -0.14
    elif word in ('pair', 'couple'):
        if previous == 'a':
            value = -0.61 if word == 'pair' else -1.55
        else:
            value = -0.33 if word == 'pair' else -1.15
    elif word == 'of' and previous in ('couple', 'pair'):
        value = -1.10 if previous == 'couple' else -0.76

    # Bare lowercase forms can instead be pieces of unrelated words.
    if token in ('ten', 'few', 'tres', 'три', 'vier'):
        if word == 'ten':
            value = -0.18
        elif word == 'few':
            value = -0.44
        else:
            value = -0.15
    return (doc, word), float(value)

"""Approximate a space boundary: excite a separately tokenized numeral;
inhibit another leading space, rather than treating it as a numeral onset.

ASCII digits immediately after a bare space receive a large positive value.
Repeated leading spaces receive negative values, strongest for a second bare
space and weaker for indentation or longer space tokens. Capitalization and
punctuation strengthen this inhibition. Tabs, other numeric tokens, and a
bare space at document start have fitted special cases. Coefficients are fitted
training averages; finer lexical effects and later numeral digits are omitted.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, indent = '', True
    else:
        _, previous, indent = carry
    value = 0.0
    bare_space = token == ' '
    leading_space = token.startswith(' ')
    rest = token.lstrip()
    capital = bool(rest) and rest[0].isupper()
    punctuation = bool(rest) and not rest[0].isalnum()

    if previous == ' ':
        if len(token) == 1 and token in '0123456789':
            value = 1.30 if token == '2' else 1.19
        elif bare_space:
            value = -2.64 + 0.49 * indent
        elif leading_space:
            value = -1.34 + 0.53 * indent - 0.56 * capital - 0.36 * punctuation
        elif token.startswith('\t'):
            value = -1.35
        elif token.isnumeric():
            value = 0.54
    elif previous and previous.strip(' ') == '' and leading_space:
        scale = len(previous) ** -0.7
        if bare_space:
            value = scale * (-1.52 + 0.30 * indent)
        else:
            value = scale * (-0.76 + 0.40 * indent - 0.29 * capital)
    elif previous == '' and bare_space:
        value = -1.08

    # Track whether the current line has contained any non-whitespace text.
    if '\n' in token:
        indent = not token.rsplit('\n', 1)[1].strip()
    elif token.strip():
        indent = False
    return (doc, token, indent), float(value)

