READS = ()

# Token fragments: these are spellings, not whole-word meanings.
AME_FRAGMENTS = {'ame': 2.5, 'ames': 2.2, 'amed': 1.35,
                 'rame': 2.6, 'amer': 1.2, 'amel': 1.2,
                 'ramer': 1.2, 'ama': 0.8, 'amas': 0.95,
                 'aming': 1.0, 'amy': 0.7, 'am': 0.15,
                 'ami': 0.4, 'amin': 0.45, 'amine': 0.4,
                 'aman': 0.55, 'ams': 0.4, 'ram': 0.3}

