programs.haiku:
"""Layer-0 MLP feature: a preposition completing a verb's or noun's frame.

What it does: the component goes strongly negative on a preposition ("on", "at", "upon",
"into", "about") when the word just before it governs that preposition, as in
"depends on", "focus on", "based on", "look at", "think about", "rely on", "reflect on". It is most negative for
"on" after the focus/dependence family, less after other frames, and only mildly
negative on "at" and "into" in general. The governing words themselves are positive:
focus, depend, rely, dependent, emphasis. "Click here" and "click to" are positive. Everything else
is near zero, and "on" after punctuation or at the start of a line is zero.

Predicted values are the per-class mean activations measured on training text.
"""

READS = ()

# Words of focus, dependence and reliance. They are positive themselves and are
# usually followed by "on".
FOCUS_WORDS = {
    "focus", "focuses", "focused", "focusing", "depend", "depends", "depending",
    "dependent", "dependence", "rely", "relies", "relying", "reliance", "emphasis",
    "concentrate", "concentrated", "attention",
}
# Words that take "on" in the sense of "about", "based on", "concerning".
ABOUT_ON = {
    "based", "click", "clicked", "clicking", "effect", "effects", "impact", "impacts",
    "only", "light", "comment", "comments", "perspective", "attack", "attacks",
    "influence", "reflect", "reflects", "reflecting", "reflection", "burden", "heavily",
    "insight", "notes", "note", "opinion", "dependency", "eye", "strike", "commenting",
    "hinge", "hinges", "hinged", "wager", "wagering", "bet", "bets", "betting", "expand",
    "expanding", "improve", "improving", "draw", "drawing", "insist", "centered", "centred",
    "concentrating", "relied", "relying", "reliant", "embark", "rely", "relies",
}
# Other verbs and nouns that take "on" ("work on", "take on", "information on").
OTHER_ON = {
    "work", "working", "worked", "take", "took", "taking", "hold", "held",
    "information", "research", "tax", "back", "put", "sitting", "down",
}
# Verbs of looking or aiming, which take "at".
LOOK_VERBS = {
    "look", "looks", "looking", "looked", "glance", "stare", "aim", "aimed",
    "point", "points", "gaze", "laugh", "smile", "shout", "arrive", "attempt",
}
# Verbs of thinking or talking, which take "about".
THINK_VERBS = {
    "think", "thinking", "talk", "talking", "talks", "talked", "worry", "worried",
    "concerned", "excited", "thought",
}
# The same prepositions in other languages (Russian на, Arabic على, Chinese 于, Vietnamese vào).
FOREIGN_ON = {
    "на": -0.3, "على": -0.9, "于": -0.5, "於": -0.5, "vào": -0.7, "pada": -0.4, "auf": -0.2,
}


def word(token):
    return token.strip().lower()


def step(carry, prefix, upstream):
    token = word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    previous = word(prefix.token_strings[-2]) if same_doc else ""
    if token in FOCUS_WORDS:
        return carry, 0.9
    if token in ("here", "to") and previous in ("click", "clicked"):
        return carry, 1.8
    if token == "in" and previous == "based":
        return carry, 3.0
    if token in ("on", "upon", "onto"):
        if previous in FOCUS_WORDS:
            return carry, -3.5
        if previous in ABOUT_ON:
            return carry, -2.5
        if previous in OTHER_ON:
            return carry, -1.0
        if not previous.isalpha():
            return carry, 0.0
        return carry, -0.3
    if token in FOREIGN_ON:
        return carry, FOREIGN_ON[token]
    if token == "at":
        return carry, -1.6 if previous in LOOK_VERBS else -1.0
    if token == "into":
        return carry, -0.7
    if token == "about" and previous in THINK_VERBS:
        return carry, -1.0
    return carry, 0.0

