"""Negative pulses for chat delimiters and capitalized underscore-name pieces.

Tool, thought, and turn markers have their own levels. Underscores joining
uppercase identifier segments give strong negative pulses; single-letter
subscripts and mixed-case names give weaker ones. Capitalized API suffixes
also respond, and uppercase continuations get smaller length-scaled pulses.
Most other text is zero. State keeps the unfinished name segment and resets
at document boundaries. Fine word-specific amplitudes are omitted.
"""
import re
READS = ()

DELIMITERS = {
    '<tool_call>': -2.76,
    '</tool_call>': -2.04,
    '<tool_response>': -2.13,
    '</tool_response>': -1.29,
    '</think>': -1.70,
    '<think>': -0.37,
    '<|im_end|>': 0.03,
}
WORD_END = re.compile(r'[A-Za-z0-9]+$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    name, previous, in_upper_name = '', '', False
    if carry is not None and carry[0] == doc:
        _, name, previous, in_upper_name = carry
    s = prefix.token_strings[-1]
    suffix = s[1:] if s.startswith('_') else ''
    letters = ''.join(c for c in name if c.isalpha())
    upper = letters.isupper()
    multi = len(letters) > 1
    value = 0.0

    if s == '<|im_start|>':
        first_turn = not previous or previous == '<|endoftext|>'
        value = -0.173 if first_turn else -0.59
    elif s in DELIMITERS:
        value = DELIMITERS[s]
