            value = -1.23 if multi else -0.29
        elif name.isdigit():
            value = -0.48
        else:
            value = 0.04 if name.islower() else -0.08
    elif suffix and suffix[0].isupper():
        if suffix.isupper():
            if upper:
                if multi:
                    value = -1.30 - 0.035 * min(len(suffix), 8)
                    if len(suffix) == 2:
                        value += 0.22
                else:
                    value = -0.60 if len(suffix) == 1 else -0.95
            elif name.islower():
                value = 0.0 if len(suffix) == 1 else -0.24
            elif name.isdigit():
                value = -0.68
            elif not name:
                value = -0.23 if len(suffix) == 1 else -1.2
            else:
                value = -0.13 if len(suffix) == 1 else -0.48
        else:
            value = -0.66 if upper and multi else -0.15
    elif in_upper_name and s.isalpha() and s.isupper():
        value = -0.06 * min(len(s), 6)

    # Spaces, punctuation, and underscores end the current name segment.
    match = WORD_END.search(s)
    if match:
        tail = match[0]
        if tail == s:
            name = (name + tail)[-64:]
        else:
            in_upper_name = bool(s.startswith('_') and upper and suffix.isupper())
            name = tail
    else:
        name, in_upper_name = '', False
    return (doc, name, s, in_upper_name), float(value)

