"""Word-class means for layers.0.mlp.down_proj:6097, plus its one clear response.

The component's activation is a dense, token-specific number: about 0.03 typical size,
with no single concept behind most of it. Its one clear response is the colon in a
document-initial 'Title:' header (+0.41), with the word 'Title' itself at -0.285. Elsewhere
the best simple prediction is the mean activation of a broad word class of the current
token, given by the table below. Those class means explain only about 0.5% of variance.
"""
import re
READS = ()

# mean activation per token class (fitted on training rows)
CLASS_MEAN = {
    "lower_piece": -0.0043,      # lowercase word fragment with no leading space ("ing", "ness")
    "lower_word_sp": 0.0011,     # lowercase word after a space
    "Cap_word_sp": -0.0038,      # capitalised word after a space (names, titles)
    "Cap_word_nosp": 0.0018,
    "allcaps": -0.0028,          # ALL-CAPS token (acronyms)
    "digits": 0.0007,
    "punct": 0.0034,             # punctuation only
    "space_only": 0.0013,        # whitespace or newlines
    "path": 0.0038,              # tokens containing / or \
    "cjk": -0.0024,              # Chinese, Japanese or Korean characters
    "mixed_alpha": -0.0006,
    "partial_utf8": -0.0049,     # half of a multi-byte character
    "other": 0.0011,
}

def token_class(s):
    c = s.strip()
    if s == "":
        return "other"
    if "�" in s:
        return "partial_utf8"
    if c == "":
        return "space_only"
    if re.fullmatch(r"[a-z]+", s):
        return "lower_piece"
    if re.fullmatch(r"[^\w\s]+", s):
        return "punct"
    if re.fullmatch(r" [a-z]+", s):
        return "lower_word_sp"
    if re.fullmatch(r" [A-Z][a-z]+", s):
        return "Cap_word_sp"
    if re.fullmatch(r"[A-Z][a-z]+", s):
        return "Cap_word_nosp"
    if re.fullmatch(r"[A-Z]+", c):
        return "allcaps"
    if any(ord(ch) > 0x2E80 for ch in s):
        return "cjk"
    if re.search(r"[/\\]", s):
        return "path"
    if re.search(r"\d", s):
        return "digits"
    if re.search(r"[A-Za-z]", s):
        return "mixed_alpha"
    return "other"

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tok = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos, prev = 0, None          # first token of a new document
    else:
        pos, prev = carry[1] + 1, carry[2]
    if pos == 0 and tok == "Title":
        value = -0.285
    elif pos == 1 and prev == "Title" and tok == ":":
        value = 0.41
    else:
        value = CLASS_MEAN[token_class(tok)]
    return (doc, pos, tok), value

programs.sol:
"""Approximate a local English modal-auxiliary feature.

'Could' produces a particularly strong negative response; other modals are
weaker. A preceding pronoun changes the strength. There are also responses
on a following question subject, negation, or auxiliary ('could be').
The rules retain some spelling/case distinctions and predict zero elsewhere;
they do not attempt to parse whole sentences or explain weaker lexical noise.
"""
READS = ()

MODALS = {
    'could': -5.13,
    'can': -1.28,
    'would': -1.17,
    'should': -1.37,
    'will': -1.05,
    'must': -1.12,
    'shall': -1.61,
    'might': -1.42,
    'may': -0.24,
}
NEGATIVE_STEMS = {'couldn': -1.75, 'wouldn': -0.63, 'shouldn': -0.69}
NEGATIVE_ENDINGS = {
    'couldn': -3.05,
    'can': -1.43,
    'wouldn': -0.91,
    'shouldn': -1.08,
    'won': -0.84,
    'isn': -0.46,
    'aren': -0.46,
    'wasn': -0.50,
    'weren': -0.47,
    'haven': -0.46,
    'hasn': -0.54,
    'hadn': -0.60,
    'didn': -0.26,
    'doesn': -0.15,
}

# Subject classes; columns are ordinary modals, 'can', and 'could'.
SUBJECT_SHIFTS = (
    ({'i', 'we'}, (0.28, 0.12, 0.63)),
    ({'you'}, (0.46, 0.0, -0.15)),
    ({'he', 'she', 'they'}, (0.10, 0.0, 0.69)),
    ({'it', 'this', 'these', 'those', 'which'}, (-0.17, -0.26, -0.70)),
)


def following_auxiliary(word, previous):
    """Small phrase-level responses on the token after an auxiliary."""
    if previous in {'could', 'can'} and word in {'i', 'you', 'we'}:
        if previous == 'could':
            return -2.8 if word == 'you' else -1.0
        return -0.8 if word == 'you' else -0.3
    if word == 'not':
        if previous == 'could':
            return -1.2
        if previous == 'can':
            return -0.48
        if previous in MODALS:
            return -0.20
        if previous in {'do', 'does', 'did'}:
            return 0.19 if previous == 'did' else 0.28
    if previous == 'could':
        return {'be': -0.74, 'have': -0.43,
                'also': -0.82, 'possibly': -0.82}.get(word, 0.0)
    if word == 'be' and previous in {'may', 'should', 'must', 'would'}:
        return 0.15
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous_raw = '' if carry is None or carry[0] != document else carry[1]
    previous = previous_raw.strip().lower()
    raw = prefix.token_strings[-1]
    spelling = raw.strip()
    word = spelling.lower()
    state = (document, raw)

    if word in ("'t", '’t'):
        return state, float(NEGATIVE_ENDINGS.get(previous, 0.0))
    if word in ("'ll", '’ll'):
        return state, -0.08 if previous == 'you' else -0.38
    if word in NEGATIVE_STEMS and raw.startswith(' '):
        return state, float(NEGATIVE_STEMS[word])
    if word == 'cannot':
        return state, -1.13
    if word == 'ought' and raw.startswith(' '):
        return state, -0.32
    if word.startswith('.') and word[1:] in MODALS:
        return state, -0.9
    if word not in MODALS:
        return state, float(following_auxiliary(word, previous))

    value = MODALS[word]
    if spelling != word and word in {'may', 'will', 'shall'}:
        return state, {'may': 0.10, 'will': -0.78, 'shall': -1.07}[word]
    if not raw.startswith(' '):
        if word == 'can':
            return state, -1.00 if raw == 'Can' else -0.72
        if word == 'could':
            return state, -4.45 if raw == 'Could' else -4.65
        return state, float(value + 0.12)

    column = 2 if word == 'could' else 1 if word == 'can' else 0
    for subjects, shifts in SUBJECT_SHIFTS:
        if previous in subjects:
            value += shifts[column]
            break
    if word == 'could' and previous != 'i':
        if previous_raw.strip()[:1].isupper():
            value -= 0.40
    return state, float(value)

"""Consonant joins across short Latin/Cyrillic word pieces.

Positive joins include liquid (r/l)-to-stop and nasal (m/n)-to-stop joins, and a
consonant doubled across the token boundary. A doubled consonant already at
the end of the previous token instead gives a negative response. Fragment
length, vowel count, and capitalization scale these responses. Diacritics are
removed; Cyrillic consonants are matched to approximate Latin equivalents.
This is a spelling-based approximation, not a full syllabifier. It reads only
the current and preceding tokens; document changes and whitespace block joins.
"""
from functools import lru_cache
import unicodedata

READS = ()
VOWELS = set('aeiouyαεηιουω')
CONSONANTS = set('bcdfghjklmnpqrstvwxz')
STOPS = set('bcdgkptq')
CYRILLIC = dict(zip('рлмнсзтдпбкгфвхжшщцчй', 'rlmnsztdpbkgfvxjssccy'))
CYRILLIC.update(dict(zip('аеёиоуыэюяіїє', 'aeeiouyeuaiie')))
CYRILLIC.update({'ь': '', 'ъ': ''})  # Signs modify a consonant, not a syllable.

@lru_cache(maxsize=8192)
def spelling(token):
    text = ''.join(c for c in unicodedata.normalize('NFD', token.lower())
                   if not unicodedata.combining(c))
    return ''.join(CYRILLIC.get(c, c) for c in text)


def join_strength(left, text):
    right = text[0]
    if left == right:
        return 0.70
    if left in 'rl':
        if right in 'rl':
            return 0.55 if left == 'r' else 0.12
        return 1.15 if right in STOPS else 0.80
    if right in 'rl':
        return 0.05
    if (left == 'm' and right in 'bp') or (left == 'n' and right in STOPS):
        return 0.80
    if left in 'sz' and right in 'ckq':
        return 0.80
    return 0.30 if left in 'mnsz' else 0.20


def fragment_scale(previous):
    fragment = previous.strip()
    vowels = sum(c in VOWELS for c in fragment)
    before = previous[-2:-1]
    if before in CONSONANTS:
        scale = -0.06
    elif not vowels:
        scale = 0.29
    elif vowels > 1:
        scale = 0.45
    else:
        scale = 0.90 if len(fragment) == 3 else 0.77
    if before not in VOWELS:
        scale *= 0.56

    return scale


def doubled_coda(previous):
    """A consonant pair already completed inside the preceding fragment."""
    last = previous[-1]
    strength = -0.55 if last in 'rlsz' else -0.39 if last in 'mn' else -0.26
    vowels = sum(c in VOWELS for c in previous)
    if not vowels:
        scale = 0.65
    elif vowels > 1:
        scale = 0.52
    else:
        scale = 1.0 if len(previous.strip()) == 3 else 0.44
    return strength * scale


def current_scale(text):
    n = len(text.strip())
    if n == 1:
        return 1.0
    if n <= 3:
        if text[1:2] in VOWELS:
            return 1.0 if n == 2 else 0.74
        return 0.66
    if n == 4:
        return 0.43
    return 0.24 if n == 5 else 0.14


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    text = spelling(raw)
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.0015
    if previous[-1:] in CONSONANTS and text[:1] in CONSONANTS:
        if len(previous) >= 2 and previous[-2] == previous[-1]:
            value = doubled_coda(previous)
        else:
            value = join_strength(previous[-1], text) * fragment_scale(previous)
        value *= current_scale(text)
        if raw[:1].isupper() and not (len(raw.strip()) > 1 and raw.isupper()):
            value *= 0.55
    return (doc, text), float(value)

