programs.sol:
"""Approximate a k/K-fragment detector using spelling and language cues.

The largest response is for a single k/K or a short fragment ending in k.
Capitalization, preceding letters and leading whitespace set its strength.
Decayed counts of English and other-language function words, plus accented
Latin letters, lower it when non-English cues predominate. Familiar k-initial
words are suppressed; an uppercase acronym continuing with K is boosted.
Short Cyrillic/Arabic counterparts and fullwidth K get fixed responses.
State resets with each document; longer words generally get little response.
This captures the main pattern, not the remaining word-specific variation.
"""
import unicodedata

READS = ()
ENGLISH_WORDS = frozenset('''
    the and of to in is for that it with are was be by from not this an or
    but have you which can we has they will their as at your who
'''.split())
OTHER_LANGUAGE_WORDS = frozenset('''
    der die das und ist mit von zu den dem ein eine nicht auch auf für
    och att som ett det er til og av ikke för med
    bir ve bu için ile çok mi és hogy nem van az egy ja että
    yang dan dari dengan ini untuk nie na je že se
'''.split())
FAMILIAR_K_WORDS = frozenset('''
    know knows known knowing keep keeps keeping kept key keys keyboard
'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    reset = carry is None or carry[0] != doc
    if reset:
        english = foreign = 0.0
    else:
        _, english, foreign = carry
    english *= 0.97
    foreign *= 0.97
    word = s.strip().lower()
    if reset or s[:1].isspace():
        english += word in ENGLISH_WORDS
        foreign += word in OTHER_LANGUAGE_WORDS
    if any(0x80 <= ord(c) < 0x250 and
           'LATIN' in unicodedata.name(c, '') for c in s):
        foreign += 1.0
    language_cue = foreign / (1.0 + english + foreign)
    carry = (doc, english, foreign)

    letters = ''.join(c for c in s if c.isalpha())
    lower = letters.lower()
    n = len(letters)
    if 'k' not in lower:
        if any(c in s for c in 'Ｋｋ'):
            value = 0.66
        elif 'к' in lower and n <= 3:
            value = 0.12
        elif any(c in s for c in 'كک') and n <= 3:
            value = 0.23
        else:
            value = 0.0
        return carry, value
    if lower in FAMILIAR_K_WORDS:
        return carry, -0.02

    space = s[:1].isspace()
    capital = letters[0].isupper()
    if n == 1:
        value = 1.44 if capital else 1.19
        value -= 0.17 * space + 1.21 * language_cue
        if not reset and capital and not space:
            previous = prefix.token_strings[-2].strip()
            if len(previous) > 1 and previous.isalpha() and previous.isupper():
                value += 0.38
    elif n == 2:
        if lower.endswith('k'):
            before = lower[0]
            if before == 'c':
                value = 0.59
            elif before == 'a':
                value = 0.73
            elif before in 'eiou':
                value = 0.90
            else:
                value = 1.14
            value -= 0.26 * space + 1.21 * language_cue
        else:
            value = 0.34 - 0.68 * language_cue
    elif n == 3:
        if lower.endswith('k'):
            if lower[-2] == 'c':
                value = 0.11
            elif 'a' in lower:
                value = 0.17
            elif lower[-2] in 'eiou':
                value = 0.45
            else:
                value = 0.55
        elif lower.startswith('k'):
            value = 0.14 if lower[1] in 'aou' else 0.41
        else:
            value = 0.16
        value -= 0.68 * language_cue
    elif lower.startswith('k'):
        value = 0.19 + 0.10 * capital - 0.39 * language_cue
    else:
        value = 0.015 - 0.16 * language_cue
    if 2 <= n <= 3:
        value += 0.11 * capital + 0.07 * letters.isupper()
    value -= (0.91 if n == 1 else 0.22) * reset
    return carry, float(value)

