"""Document delimiters and horizontal whitespace.

End-of-text markers give a large positive response. Long horizontal padding
is negative, most strongly near 16--20 spaces or four tabs. Padding at the
start of a line is less negative than padding following text. Four-column
alignment also matters. A literal "Title" header at document start is
also positive. Ordinary text is approximated by zero.
"""
READS = ()


def space_padding(width, line_start):
    # A broad trough around 17 columns, recovering at larger widths.
    value = -0.214 - 0.037 * min(width - 8, 9)
    value += 0.021 * max(0, min(width - 19, 13))
    if width % 4 == 3:
        value += 0.112
    if line_start:
        value += 0.123
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    blank = first or carry[1]
    s = prefix.token_strings[-1]
    n = len(s)
    value = 0.0
    if s == '<|endoftext|>':
        value = 0.99 if first else 1.50
    elif first and s == 'Title':
        value = 1.26
    elif s and s.strip(' ') == '':
        if n >= 8:
            value = space_padding(n, blank)
        elif n == 7:
            value = 0.03 + 0.06 * blank
        elif n == 4:
            value = 0.01 + 0.04 * blank
        elif n == 2:
            value = -0.025
    elif s and s.strip('\t') == '':
        # Repeated tabs have the same broad negative response as padding.
        if n == 1:
            value = 0.02 + 0.03 * blank
        else:
            value = -0.32 - 0.13 * min(n - 2, 2)
            value += 0.06 * max(0, min(n - 4, 4))
            value += 0.13 * blank
    elif s.startswith('\t') and s[1:] and s[1:].strip(' ') == '':
        if n >= 9:
            value = space_padding(n, blank) + 0.10
        else:
            value = 0.08 + 0.08 * blank
    elif s and s.strip('\u00a0') == '':
        value = 0.055 if n == 1 else -0.04 * n
        if n >= 8:
            value -= 0.12

    # Carry only the document and whether the current line is still blank.
    if '\n' in s:
        tail = s.rsplit('\n', 1)[1]
        blank = not tail or tail.isspace()
    elif not s.isspace():
        blank = False
    return (doc, blank), float(value)

"""A local phrase detector for manner, discourse, timing and sequence.

It predicts positive completions of 'in this way', 'in other words',
'after all', and references to sections. Timing/ordering expressions and
some verb-particle pairs instead receive negative scores. It remembers
only five tokens, resets between documents, and handles document openings
and tool-message boundaries separately. Otherwise unlisted responses
are zero: this captures salient constructions, not every lexical detail.
"""
READS = ()

COME = {'come', 'comes', 'came', 'coming'}
START = {'start', 'starts', 'started', 'starting', 'begin', 'began', 'beginning'}
TIMING = {'early', 'earlier', 'late', 'later', 'latest', 'recent', 'previous',
          'final', 'lastly', 'post', 'mid'}
ORDER = {'first', 'second', 'third', 'last', 'next'}
REFERENCE = {'this', 'that', 'same', 'other', 'another', 'first', 'second',
             'following'}
PHRASES = {
    ('other', 'words'): 1.22,
    ('after', 'all'): 1.10,
    ('at', 'all'): 0.32,
    ('in', 'all'): 0.21,
    ('same', 'time'): 0.26,
    ('this', 'case'): 0.21,
    ('this', 'point'): 0.31,
    ('other', 'side'): 0.50,
    ('here', "'s"): -0.18,
    ('followed', 'by'): -0.19,
    ('next', 'to'): -0.32,
    ('last', 'year'): -0.21,
    ('next', 'year'): -0.39,
}
COME_PARTICLES = {
    'in': -0.72, 'on': -0.61, 'up': -0.54, 'out': -0.58,
    'into': -0.44, 'from': -0.20, 'to': -0.16, 'with': -0.22,
}


def response(token, history):
    word = token.strip().lower()
    prev = history[-1] if history else ''
    bare = word.lstrip('-')
    recent = history[-4:]
    if token.startswith('</tool_'):
        return 0.13
    if token.startswith('<tool_'):
        return 0.10
    if token in {'<|im_start|>', '<|im_end|>'}:
        return -0.03
    if (prev, word) in PHRASES:
        return PHRASES[prev, word]
    if word in {'way', 'ways', 'manner'} and token.startswith(' '):
        value = 0.14
        if 'in' in recent:
            value += 0.45 if word == 'way' else 0.35
        if prev in REFERENCE:
            value += 0.55
        elif prev in {'any', 'such', 'best', 'better', 'new', 'different',
                      'many', 'several', 'various'}:
            value += 0.30
        return 1.25 if word == 'way' and prev == 'this' and 'in' in recent else value
    if word in {'section', 'sections'}:
        if prev in REFERENCE | {'next', 'last', 'previous'}:
            return 0.72 if 'in' in recent or prev in {'next', 'previous'} else 0.35
        return 0.0
    if word in {'have', "'ve", '’ve'}:
        if 'once' in recent or 'after' in recent:
            return 0.72 if word == 'have' else 0.90
        return 0.04 if word == 'have' else 0.17
    if prev == 'after':
        if word in {'ward', 'wards'}:
            return 1.40 if word == 'ward' else 0.85
        if word in {'the', 'a', 'an', 'you', 'we', 'they'}:
            return 0.28
        if word in {'that', 'which', 'each', 'every', 'these', 'another'}:
            return 0.48
    if prev in COME:
        return COME_PARTICLES.get(word, 0.0) * (1.3 if prev == 'coming' else 1.0)
    if bare in {'in', 'on'}:
        if prev in TIMING:
            return -0.85 if bare == 'on' else -1.00
        if prev in ORDER:
            return {'next': -1.45, 'first': -0.75, 'last': -0.75}.get(prev, -0.50)
        if prev in START or prev == 'arrived':
            return -0.50
        if prev in {'here', 'back', 'end', 'ending', 'already'}:
            return -0.32
    if bare == 'up':
        if prev in {'follow', 'followed', 'following'}:
            return -1.06 if word.startswith('-') else -0.91
        if prev in ORDER | {'previous'}:
            return -1.80 if prev == 'next' else -1.10
        if prev in START:
            return -0.78 if word.startswith('-') else -0.35
        if prev in {'end', 'finish', 'finishing', 'finished'}:
            return -0.30
    if word == 'out' and prev == 'starting':
        return -0.46
    if prev in ORDER:
        if bare in {'gen', 'generation'}:
            return -1.40 if prev == 'next' else -0.60
        if bare == 'person':
            return -0.90 if prev == 'first' else -0.60
        if word in {'thing', 'question', 'issue', 'door', 'level'}:
            return -0.90 if prev == 'next' else -0.55
    if word in {'life', 'retirement'} and prev == 'early':
        return -0.80
    if word == 'issue':
        return -0.60 if prev in TIMING | {'this', 'new', 'another'} else -0.14
    return 0.10 if word == 'words' else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = response(token, history)
    if not history:
        word = token.strip().lower()
        value = 0.025
        if token.startswith('#'):
            value = 0.22
        elif word in ORDER | {'once', 'another', 'after'}:
            value = 0.45
        elif word in {'in', 'out', 'come', 'from'}:
            value = -0.20
        elif '\n' in token:
            value = -0.05
        elif token == '<|im_start|>':
            value = 0.07
    return (doc, (history + (token.strip().lower(),))[-5:]), float(value)

programs.haiku:
"""Word-level reading of one MLP direction in layer 0 (Qwen3-1.7B, layer 0, down_proj component 6107).

What it responds to, in plain words:
- Positive: "way" / "ways" / "words" / "manner" closing an idiom: "In this way",
  "in another way", "In other words", "in a way". Weaker for "the way", and a little
  for patent-style "section", "embodiment", "paragraph", clause, and contractions 've.
- "After all" (the "all" that closes it) is positive.
- Negative: a particle right after a word of coming, following or early/later timing:
  "came up", "come out", "follow up", "early in", "later in", "comes in".
- Negative: "generation" in "next generation" (and "-gen" / "-generation" compounds).
- Mildly negative: "issue", "question", "reason", "able", "having", "life", "person".
Everything else predicts 0; most of the component's variance is a long, diffuse tail of
small token-specific values that this short list does not capture.
"""
READS = ()

MANNER = {"way", "ways", "words", "manner"}
STRONG_OPENERS = {"this", "other", "another", "any", "some", "same", "best"}
PATENT = {"embodiment", "embodiments", "paragraph", "subparagraph", "subsection", "clause"}
ARRIVAL = {"come", "came", "comes", "coming", "follow", "followed", "early", "later", "latest", "earlier"}
PARTICLES = {"in", "out", "up", "on"}
MATTER = {"issue", "question", "reason"}
MILD_NEG = {"able", "having", "life", "person"}
GENERATION = {"generation", "-generation", "-gen"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if cur in MANNER:
        value = 0.9 if prev in STRONG_OPENERS else 0.2
    elif cur == "all" and prev == "after":
        value = 1.1
    elif cur == "section" and prev in {"this", "next"}:
        value = 0.6
    elif cur in PATENT or cur == "'ve" or cur == "’ve":
        value = 0.2
    elif cur in PARTICLES and prev in ARRIVAL:
        value = -0.9
    elif cur in GENERATION and prev == "next":
        value = -1.2
    elif cur in GENERATION:
        value = -0.2
    elif cur in MATTER:
        value = -0.15
    elif cur in MILD_NEG:
        value = -0.1
    else:
        value = 0.0
    return carry, value

programs.luna:
"""A small lexical sketch for a handful of words with positive responses.

Most positions are left at zero.  Method words and names for text units get a
modest positive prediction; surrounding context is not modeled.
"""

READS = ()

METHOD_WORDS = {"way", "ways", "manner"}
TEXT_UNITS = {
    "word", "words", "line", "lines", "section", "subsection", "paragraph"
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in METHOD_WORDS:
        return None, 0.25
    if word in TEXT_UNITS:
        return None, 0.25
    return None, 0.0

programs.sol:
"""A seven-related lexical detector, with weaker responses to July.

Give positive values to digit 7, seven-related English words and stems,
and several other written forms of seven. The gains are training estimates.
For digit 7, lower the response after digits and decimal separators, boost
it after an adjacent ASCII letter, and add a small early-document boost.
Other tokens' small, unrelated lexical responses are left at zero.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ""
    else:
        _, position, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    value = 0.0

    if token == "7":
        value = 1.00 + 0.09 * math.exp(-position / 64.0)
        if previous.isdigit():
            value -= 0.05
        elif previous in {".", ","}:
            value -= 0.11
        elif previous and previous[-1].isascii() and previous[-1].isalpha():
            value += 0.20
        if previous == "7":
            value -= 0.06
    elif word == "７":
        value = 0.82
    elif lower in {"seven", "seventh", "sevent"}:
        value = 1.28
        if lower == "seventh":
            value = 1.23
        elif lower == "sevent":
            value = 1.17
        if word[0].isupper():
            value = {"seven": 1.41, "seventh": 1.51, "sevent": 0.91}[lower]
    elif lower == "-seven":
        value = 1.70
    elif lower in {"seventeen", "seventeenth", "seventy", "seventieth"}:
        value = 0.86 if lower.startswith("seventeen") else 0.97
    elif word == "venth" and previous.lower().rstrip().endswith("se"):
        # For example: Se + venth, or twenty-se + venth.
        value = 1.10
    elif word == "eenth" and previous.lower().rstrip().endswith("sevent"):
        value = 0.90
    elif word == "七":
        value = 1.62
    elif word == "第七":
        value = 1.39
    elif word == "十七":
        value = 1.15
    elif word in {"七月", "七十"}:
        value = 0.90
    elif word == "柒":
        value = 0.62  # Chinese financial numeral seven.
    elif word == "VII":
        value = 0.53
    elif word in {"семь", "сем"}:
        value = 0.63 if word == "семь" else 0.51
    elif word == "sept":
        value = 0.21  # French seven.
    elif word == "กรกฎาคม":
        value = 0.31  # Thai July.
    elif word == "July":
        value = 0.56 if token.startswith(" ") else 0.41
    elif word == "Jul" and token.startswith(" "):
        value = 0.21

    return (doc, position + 1, token), float(value)

"""A local vocabulary detector, chiefly for location versus deciding.

Location words give a large negative response, with weaker responses for
positions, addresses, and finding. Deciding gives a positive response.
Immediate continuations ('location of', 'Location:', 'decided to') retain
part of that response. 'When' and 'where' also affect following pronouns.
Other tokens are approximately silent. This is a lexical approximation,
not a general classifier of whether a sentence describes a place.
"""

READS = ()

# Each group is ordinary vocabulary, including code abbreviations and
# translations. Weights summarize responses measured on training text.
GROUPS = (
    (-0.85, {'located', 'loc', 'vicinity', 'address', 'addresses', 'addr'}),
    (-0.65, {'locate', 'locating', 'addressed', 'addressing'}),
    (-0.45, {'relocate', 'relocated', 'relocation'}),
    (-0.9, {'destination', 'destinations'}),
    (-0.8, {'physical'}),
    (-1.0, {'physically'}),
    (-1.4, {'spot'}),
    (-1.15, {'spots'}),
    (-0.5, {'spotted', 'spotting'}),
    (-0.3, {'found'}),
    (-0.12, {'find'}),
    (-0.8, {'anywhere', 'wherever'}),
    (-0.45, {'somewhere'}),
    (-0.08, {'where', 'area'}),
    (-0.3, {'areas', 'venue', 'venues'}),
    (-0.35, {'positioning', 'positional'}),
    (-0.18, {'positioned'}),
    (-4.2, {'位置', '的位置'}),               # position / location
    (-2.2, {'地点', '地點', '地理位置', '위치'}),
    (-1.5, {'地址', '哪里', '哪裡', '在哪里', 'どこ'}),
    (-0.9, {'地方', '的地方', '处', '處', '位于', '位於', '所在',
            '定位', '这里', '這裡', '那里',
            'адрес', 'мест', 'место'}),
    (1.0, {'决定', '決定'}),                # decide
)
VALUES = {word: value for value, words in GROUPS for word in words}
DECIDING = {'decide', 'decides', 'decided', 'deciding'}
PRONOUNS = {'i', 'we', 'you', 'he', 'she', 'they', 'it'}
PERSONAL_SUBJECTS = PRONOUNS - {'it'}
CLAUSE_PRONOUNS = PRONOUNS - {'i'}
# Composition, proposition, superposition, etc. are not spatial position.
NONSPATIAL_PREFIXES = {'com', 'decom', 'pro', 'sup', 'super', 'superim',
                       'im', 'dis', 'ex', 'inter', 'de'}


def spelling(text):
    word = text.strip().strip('._-/([<,')
    for verb in ('get', 'set'):
        if word.startswith(verb) and word[len(verb):len(verb) + 1].isupper():
            word = word[len(verb):]
            break
    return word.lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, raw_previous = '', ''
    else:
        previous, raw_previous = carry[1:]
    word = spelling(text)
    value = VALUES.get(word, 0.0)
    context_word = word

    if word in {'location', 'locations'}:
        value = -4.1 if word == 'location' else -3.75
        if text.strip()[:1].isupper():
            value = -4.75 if text[:1].isspace() else -4.2
        elif text.startswith(('.', '_', '(')):
            value = -3.6
        if not text[:1].isspace() and previous in {'trans', 'dis', 'col'}:
            value = -1.4  # translocation, dislocation, collocation
            context_word = ''
    elif word in {'position', 'positions'}:
        value = -1.2 if word == 'position' else -1.1
        if not text[:1].isspace() and previous in NONSPATIAL_PREFIXES:
            value = -0.05
            context_word = ''
    elif word == 'pos':
        abbreviated_identifier = text.strip().startswith('_') or text.strip() == 'Pos'
        value = -0.85 if abbreviated_identifier else -0.45
    elif word in DECIDING:
        value = 0.9 if word == 'deciding' else 1.2
        if word == 'decided' and previous in PERSONAL_SUBJECTS:
            value = 1.45
        elif word == 'decide' and previous == 'you':
            value = 2.0
    elif word == 'found' and previous in {'be', 'not'}:
        value = -0.6

    if word == 'of':
        if previous in {'location', 'locations'}:
            value = -2.3
        elif previous in {'position', 'positions'}:
            value = -0.9
        elif previous in {'address', 'addresses', 'vicinity', 'spot'}:
            value = -0.45
    elif text.strip() == ':' and previous in {'location', 'locations'}:
        value = -1.4 if raw_previous.strip()[:1].isupper() else -0.5
    elif previous in DECIDING and word in {'to', 'that', 'it'}:
        value = 0.85 if word == 'to' and previous == 'decided' else 0.65
    elif previous == 'located' and word in {'in', 'at'}:
        value = -0.13 if word == 'in' else -0.25
    elif previous == 'when' and word in CLAUSE_PRONOUNS:
        value = 0.5 if word == 'it' else 0.2
    elif previous == 'where' and word in CLAUSE_PRONOUNS:
        value = -0.15

    return (doc, context_word, text), value

programs.haiku:
"""Layer-0 MLP unit 6111 (down_proj): a quantifier detector.

The unit reads the quantity word a phrase is built around. It is strongly
negative on the universal or quantity word right after "for" ("for each",
"for every", "for purposes", and more weakly "for all", "for some", "for most",
"for several", "for many", "for various", "for certain"), and mildly negative on
sequence words after "the" ("the last", "the next", "the past", "the first",
"the entire"). It is positive on small-amount words: "few" ("a few", most
strongly), and weakly "little", "couple", "fewer", "day". Everywhere else it
predicts 0. Context is the previous token, reset at document starts.

Measured on 1024 eval rows: variance explained 0.124, r 0.35; the program put
into the model moves the output by KL 6.4e-6 nats per position against 6.7e-6
for switching the unit off (kl_fraction 0.955).
A bigram lookup table would fit far more of the variance, but it is not a concept.
"""
READS = ()

FOR_UNIVERSAL = {" each", " every", " purposes", " purpose"}
QUANTIFIERS = {" all", " some", " several", " most", " many", " various", " certain"}
TIME_WORDS = {" first", " next", " last", " past", " entire"}
SMALL_AMOUNT = {" few": 0.8, " little": 0.2, " couple": 0.2, " fewer": 0.2, " day": 0.17}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    value = 0.0
    if prev in (" for", "For"):
        if cur in FOR_UNIVERSAL:
            value = -1.3
        elif cur in QUANTIFIERS:
            value = -0.6
    elif prev == " the" and cur in TIME_WORDS:
        value = -0.3
    if cur in SMALL_AMOUNT:
        value = SMALL_AMOUNT[cur]
    if cur == " few" and prev in (" a", "A", " A", " the"):
        value = 0.8
    return carry, value

programs.sol:
"""A sparse lexical feature with Chinese/Taiwanese and alternative-transition peaks.

Read only the newest token. Recognize location-marker 在, Taiwanese city
spellings, corner quotes, and 'alternatively'. Smaller rules distinguish
Chinese grammatical words and a few formal/public-information vocabulary
classes. Other Han tokens get a length/script baseline; other tokens zero.
Remember Japanese kana and traditional Chinese spelling cues in the document
to calibrate quotes and the baseline, and the previous word for 市 after cities.
This is an approximation: it does not model the many other lexical responses.
"""
READS = ()

TAIWAN_CITIES = {'台北', '臺北', '台南', '臺南', '台中', '臺中',
                 '高雄', '桃園', '新北', '新竹', '嘉義', '基隆'}
TAIWAN_NAMES = {'台灣', '臺灣', '台湾'}
PRONOUNS = {'我', '你', '他', '她', '它', '这', '這', '那'}
LINKING_PARTICLES = {'之', '以', '及', '跟', '所', '依', '亦'}
FUNCTION_WORDS = {'的', '和', '了', '是', '有', '为', '為', '不',
                  '上', '下', '从', '從', '就', '也', '用', '将', '將'}
SIZE_WORDS = {'一', '小', '大', '高', '新', '长', '長', '多', '少'}
INSTITUTIONS = {'公司', '大学', '大學', '研究所', '学校', '學校',
                '政府', '集团', '集團', '國', '国', '教育', '教育部'}
INFORMATION_MEDIA = {'資訊', '资讯', '影音', '電腦', '电脑'}
PHYSICIANS = {'醫師', '医师'}
COORDINATION = {'配合', '搭配', '協助', '协助'}
PUBLIC_GROUPS = {'民眾', '民众', '各界', '族群', '上班族', '各位'}
# Common characters distinctive of traditional Chinese orthography.
TRADITIONAL = set(
    '臺灣縣區國學醫療資訊計畫協眾與為後時來個會電車書場'
    '體龍門馬風魚鳥雲葉萬億廣樂華東條過這進業產務員長'
    '處應開關聽說讀寫買賣見觀親愛歡發現實驗試機師設備'
    '確報導認識單數據種辦變總運動經濟聯結連續際護環節'
    '舊頭線網問歲點聲調邊對還幾讓樣達選熱於價質專題負'
    '責貴輕廠講標準義獎頁園壓壞滿燈飲飯館樓製幫婦兒層'
    '參採獨雖舉從錄隻則別訓營課勢測證檢錯補償號'
)


def han(c):
    return '\u3400' <= c <= '\u9fff'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        japanese, traditional, previous = False, False, ''
    else:
        _, japanese, traditional, previous = carry
    raw = prefix.token_strings[-1]
    text = raw.strip()
    japanese |= any('\u3040' <= c <= '\u30ff' for c in text)
    traditional |= any(c in TRADITIONAL for c in text)
    word = text.lower()
    if word == 'alternatively':
        value = 0.80 if raw.startswith(' ') else 0.77
    elif word in ('alternative', 'alternatives'):
        value = 0.23
    elif word in ('taipei', 'taiwan'):
        value = 1.0 if word == 'taipei' else 0.49
    elif text in TAIWAN_CITIES or text.removesuffix('市') in TAIWAN_CITIES:
        value = 2.6
    elif text in TAIWAN_NAMES:
        value = 1.7 if text == '台湾' else 1.3
    elif text in ('在', '，在'):
        value = 0.87 if not raw.startswith(' ') else 0.70
    elif text.endswith('在') and text not in ('现在', '現在', '存在', '正在'):
        value = 0.76
    elif text.startswith('在') and len(text) > 1:
        value = 0.60 if text != '在一起' else -0.20
    elif text == '「':
        value = 0.40 if japanese else 0.80
    elif text == '」':
        value = 0.11 if japanese else 0.40
    elif text == '《':
        value = -0.28
    elif text == '</tool_call>':
        value = 0.21
    elif text and all(han(c) for c in text):
        if text in PRONOUNS:
            value = -0.24
        elif text in FUNCTION_WORDS or text in SIZE_WORDS:
            value = -0.13
        elif text in LINKING_PARTICLES:
            value = 0.50
        elif text in ('等', '被', '要', '还', '還', '好', '又'):
            value = -0.26
        elif text.endswith('的'):
            value = -0.16
        elif text in INSTITUTIONS:
            value = 0.35
        elif text in INFORMATION_MEDIA:
            value = 0.95
        elif text in PHYSICIANS:
            value = 1.10
        elif text in COORDINATION:
            value = 1.10
        elif text in PUBLIC_GROUPS:
            value = 1.20
        elif text == '林':
            value = 0.74
        elif text in ('台', '臺', '市', '县', '縣'):
            value = 1.4 if text == '市' and previous in TAIWAN_CITIES else 0.50
        elif text in ('年', '月', '日'):
            value = -0.07
        else:
            value = {1: -0.02, 2: 0.10, 3: 0.05}.get(len(text), 0.0)
            if len(text) <= 2 and traditional and not japanese:
                value += 0.06 if len(text) == 1 else 0.09
            if len(text) <= 2 and any(c in TRADITIONAL for c in text):
                value += 0.05 if japanese else 0.07
    else:
        value = 0.0
    return (doc, japanese, traditional, text), float(value)

