"""Detect punctuation introducing a new line, rather than newlines in general.

The punctuation and line break must share a token. Opening curly braces are
strongest, followed by colons and other opening brackets. Comment delimiters,
triple quotes, and Markdown separators also respond. A literal backslash after
an introducer, as in escaped source text, gives a weaker response.
"""
READS = ()

# Strengths for familiar punctuation immediately preceding a line break.
INTRODUCERS = {
    '{': 1.9,
    ':': 1.04,
    '：': 0.73,
    '(': 0.8,
    '[': 1.0,
    '<': 0.45,
    '>': 0.33,
    '`': 0.31,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if '\n' not in token:
        if token.endswith('\\'):
            head = token[:-1]
            if head.endswith('{'):
                return None, 0.53 if head.startswith(' ') else 0.15
            if head.endswith(':'):
                return None, 0.44
        return None, 0.0

    head = token.split('\n', 1)[0].rstrip()
    bare = head.strip()
    value = INTRODUCERS.get(head[-1:], 0.0)
    if head.endswith(':'):
        if bare == ':' and head.startswith(' '):
            value = 0.56
        elif head.endswith(('":', "':")):
            value = 0.79
        if token.count('\n') >= 3:
            value *= 0.61
    elif head.endswith('{') and '\r' in token:
        value += 0.32
    elif bare.startswith('/*') and not bare.endswith('*/'):
        value = 1.85
    elif head.endswith('*/'):
        value = 0.60
    elif head.endswith(('"""', "'''")):
        value = 1.1
    elif len(bare) >= 3 and set(bare) <= {'-', '*', '_'}:
        value = 0.52
    return None, float(value)

