programs.sol:
"""Approximate the training response concentrated on English -ary/-ory endings.

Suffix pieces and a few -ary words are strong; spelling lookalikes are weak.
Most plural forms are quieter. Smaller responses cover final-y neighbors and
numerical-base/document-organization terms. Only this token is used; weak
responses outside these groups and contextual modulation are omitted.
"""
import re
READS = ()

STRONG_ARY = {
    'binary': 5.6, 'unary': 4.1, 'summary': 3.25, 'boundary': 3.6,
    'secondary': 3.1, 'diary': 3.6, 'elementary': 3.7,
    'supplementary': 3.3, 'temporary': 2.45,
}
WEAK_ARY = {
    'library', 'january', 'february', 'military', 'coronary', 'dictionary',
    'salary', 'contemporary', 'complementary', 'vocabulary',
}
QUIET_ARY = {'vary', 'legendary', 'revolutionary', 'evolutionary'}
QUIET_ORY = {
    'story', 'history', 'category', 'theory', 'victory', 'glory',
    'trajectory', 'phosphory', 'inflammatory',
}
ENDING_PIECES = {
    'ary': 4.0, 'inary': 4.4, 'aries': 2.55, 'uary': 1.9,
    'atory': 3.1, 'actory': 3.1, 'itory': 3.1, 'ductory': 3.6,
    'illary': 2.5, 'iliary': 3.3, 'ibrary': 2.5, 'irectory': 3.3,
    'plementary': 2.6, 'ory': 1.55, 'ories': 1.55, 'ery': 1.2,
    'ury': 1.05, 'ry': 0.35,
}


def response(token):
    match = re.search(r'[A-Za-z]+$', token)
    if not match:
        return 0.0
    word = match.group().lower()
    if word in ('very', 'every', 'query', 'delivery', 'series', 'robbery'):
        return 0.0
    if word == 'mary':
        return 3.5 if token == 'mary' else 1.4
    if word in ENDING_PIECES:
        return ENDING_PIECES[word]
    plural = word.endswith('ies')
    word = word[:-3] + 'y' if plural else word
    scale = 0.65 if plural else 1.0
    if word.endswith('ary'):
        value = STRONG_ARY.get(word, 1.4)
        if word in WEAK_ARY:
            value = 0.75
        if word in QUIET_ARY:
            value = 0.0
        return value * scale
    if word.endswith('ory'):
        if word in QUIET_ORY:
            return 0.15
        if word in ('territory', 'regulatory', 'mandatory', 'statutory',
                    'contradictory', 'satisfactory'):
            return 0.5
        return (1.85 if word == 'memory' else 1.45) * scale
    if word.endswith('ery'):
        places = {'bakery': 1.3, 'brewery': 1.3, 'grocery': 1.5,
                  'gallery': 1.1, 'nursery': 2.75}
        return places.get(word, 0.45) * scale
    if word in ('family', 'assembly', 'entry', 'ministry', 'poetry', 'registry'):
        return 1.1 * (0.75 if plural else 1.0)
    if word.endswith(('ority', 'arily')):
        return 0.6
    if word in ('decimal', 'hexadecimal'):
        return 1.45 if word == 'decimal' else 0.8
    if word in ('header', 'metadata', 'review', 'warning', 'warnings'):
        return 0.65
    return 0.95 if word == 'background' else 0.0


def step(carry, prefix, upstream):
    return None, response(prefix.token_strings[-1])

"""A short-line ending detector, not a general newline counter.

Newlines have a strong positive response after short lines and a much weaker
response after long lines. A smooth token-length decay models this pattern.
Paragraph breaks, recent newline frequency, indentation, trailing whitespace,
and punctuation attached to the newline adjust the response. The first line
of a document is discounted. Most other tokens have almost no response.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', 0.0, '', True, 0)
    _, n, line, density, previous, first_line, position = carry

    if '\n' in s:
        before_break = s.split('\n', 1)[0]
        text = line + before_break
        mark = before_break.strip()
        short = 1.0 / (1.0 + (n / 8.7) ** 2.5)
        broad = 1.0 / (1.0 + n / 55.0)
        indent = min(4, len(text) - len(text.lstrip()))
        if not mark:
            value = 0.48 + 2.20 * short - 0.48 * broad
            if n == 0:
                value -= 0.29
            if len(text.split()) > 4:
                value -= 0.85 * (1.0 - broad)
            if not any(c.isalnum() for c in text):
                value -= 0.39 * short
            spaces = len(before_break) - len(before_break.rstrip())
            value -= 0.80 * min(8, spaces) / 8.0 * short
            if previous == '<|im_end|>':
                value -= 0.46 * short
            value += 0.15 * max(0.0, 1.0 - position / 24.0) * short
        else:
            value = -0.24 + 1.26 * short + 0.67 * broad
            if not any(c.isalpha() for c in previous):
                value -= 0.37 * short
            if mark.endswith('{'):
                value -= 0.57 * short
            value -= 0.15 * min(4, max(0, len(mark) - 1)) * short
        value += short * (1.10 * density - 0.26 * indent / 4.0)
        if first_line:
            value -= 0.63 * short
        if s.count('\n') > 1:
            value += 0.26 - 0.30 * short
        line, n, first_line = s.rsplit('\n', 1)[-1], 0, False
    else:
        stripped = s.strip()
        if s == '<|endoftext|>':
            value = 0.98
        elif stripped == ';':
            value = 0.37
        elif stripped in {'##', '###'}:
            value = 0.40
        else:
            value = 0.006
        line += s
        n += 1
    density = 0.95 * density + 0.05 * ('\n' in s)
    return (doc, n, line, density, s, first_line, position + 1), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:6118 - a line-break detector.

The component writes a positive value on the token that ends a line, and on the
end-of-text token. It is near zero on ordinary words, digits, spaces and punctuation.
Line-break tokens are read by their shape:
- a plain newline ("\n", "\n\n", ":\n", "]\n", "\r\n") is strong;
- a break right after a full stop (".\n", ".\n\n") is weaker;
- a break with a leading space (" \n", " \n\n", " }\n") is in between;
- a break that closes a chat turn or tool tag (after "user", "assistant", "<tool_call>",
  or any tag ending in ">") is the strongest.
"""

READS = ()

END_OF_TEXT = "<|endoftext|>"
PLAIN = 1.2
AFTER_FULL_STOP = 0.4
AFTER_SPACE = 0.7
AFTER_CHAT_TAG = 2.2


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok == END_OF_TEXT:
        return carry, 1.0
    if "\n" not in tok:
        return carry, 0.0
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    if prev in ("user", "assistant") or prev.endswith(">"):
        return carry, AFTER_CHAT_TAG
    if tok.startswith("."):
        return carry, AFTER_FULL_STOP
    if tok.startswith(" "):
        return carry, AFTER_SPACE
    return carry, PLAIN

