programs.sol:
"""Recognize iv/ив spellings, especially short fragments and initial stems.

Short fragments ending in iv have the strongest negative response. Longer
civil-, liv-, priv-, div-, and riv- spellings retain weaker responses, while
ordinary -ive endings are much weaker. Short rev-/inv-/prov- fragments and invalid
also receive weaker negative predictions. The state is the unfinished word,
reset at new documents; it distinguishes productive adjective suffixes split across
tokens from stronger root fragments.
"""
import re

READS = ()


def response(token, previous):
    s = token.strip().strip('._<>-/\\:;()[]{}\"\'').lower()
    n = len(s)
    before = previous.lower() if token[:1].isalpha() else ''
    if s == 'iv':
        if token.strip() == 'IV' and token[:1].isspace():
            return -3.8
        return -4.1 if before.endswith(('at', 'ot', 'it', 'ct', 'pt')) else -4.8
    if s == 'ив':
        if before.endswith(('ат', 'от')):
            return -2.3
        return -5.1 if before in ('пр', 'тр') else -3.6
    if 'iv' in s:
        if s == 'hiv':
            return -1.7
        if s.endswith('iv'):
            if s in ('liv', 'riv', 'civ', 'priv'):
                return -4.0
            return -3.0 if s == 'div' else (-2.0 if n <= 4 else -1.2)
        if s.startswith(('civil', 'civic')):
            return -2.8 if n <= 5 else -0.6
        if s.startswith((
            'liv', 'aliv', 'priv', 'riv', 'div', 'trivi', 'reviv', 'pivot',
        )):
            if s.startswith(('privac', 'dividend')):
                return -1.6
            if s.startswith((
                'divide', 'divid', 'diverse', 'lived', 'liver', 'lively',
            )):
                return -0.4
            return -1.2
        if s.startswith(('ivil', 'ivial')):
            return -3.4
        if s.startswith('iv'):
            if s.startswith('ive'):
                return -0.1 if before.endswith(('ct', 'pt')) else -0.8
            return -1.8 if n <= 4 else -0.9
        if s.startswith('surviv'):
            return -0.7
        if s.startswith('equiv'):
            return -0.5
        return -0.05
    if 'ив' in s:
        return -1.7 if s.endswith('ив') and n <= 4 else -0.4
    if s.endswith('в'):
        if s.endswith(('ыв', 'ув')):
            return -1.2 if n <= 3 and s != 'чув' else -0.1
        if s.endswith('ав'):
            return -0.7 if n <= 3 else -0.2
        if s.endswith('ев'):
            return -0.5
        if s.endswith('ов'):
            return -0.8 if s.startswith(('пров', 'пов')) else -0.1
    if s.startswith('invalid'):
        return -0.9
    if s.isascii() and s.isalpha() and s.endswith('v') and n <= 5:
        if s.startswith(('rev', 'lev', 'inv', 'nerv', 'perv')):
            return -1.1
        if s.startswith('prov'):
            return -1.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, previous)
    tail = re.search(r'[^\W\d_]+$', token)
    word = '' if tail is None else tail.group()
    if tail is not None and tail.start() == 0:
        word = previous + word
    return (doc, word[-24:]), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:6121 -- an "iv" spelling detector.

This component goes strongly negative on the current token when that token is a bare
"iv" fragment: the letters i-v as they occur inside split words such as "anti|viral",
"Cri|velli", "Pri|vet", "di|vision", or the Cyrillic "ив" in "Пр|ивет". Whole words that
merely contain "iv" get a weaker negative value, and a few common words where "iv" is not
a syllable (give, five) get none.

The program reads only the newest token (prefix.token_strings[-1]), so it is stateless.
"""

READS = ()

# Bare fragments spelled "iv" / "ив" (optionally with a leading consonant, in any case).
IV_FRAGMENTS = {"iv", "ив", "div", "liv", "riv", "priv", "civ", "viv", "piv"}
# Common words containing "iv" where it is not a split-off syllable.
NOT_SYLLABLE = {"give", "given", "gives", "giving", "five"}

FRAGMENT_VALUE = -4.0      # typical activation on a bare "iv" fragment
SHORT_VALUE = -0.6         # short piece containing "iv", e.g. "ivo", "iva", "ives", "live"
WORD_VALUE = -0.35         # longer word containing "iv", e.g. "living", "private", "division"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token in NOT_SYLLABLE:
        value = 0.0
    elif token in IV_FRAGMENTS:
        value = FRAGMENT_VALUE
    elif "iv" in token or "ив" in token:
        if len(token) <= 5:
            value = SHORT_VALUE
        elif token.endswith("ive") or token.endswith("ively"):
            value = 0.0
        else:
            value = WORD_VALUE
    else:
        value = 0.0
    return carry, float(value)

