programs.sol:
"""A surface-text detector of assertions, expected results, and test diagnostics.

Assertion names get a large negative response; equality assertions are strongest.
Expectation words, matchers, test runners, and printing/logging get smaller ones.
Ambiguous words use nearby code/test cues, not an assessment of correctness.
The previous token recognizes split names; 240 characters supply context cues.
State resets for each document. Unrecognized tokens predict zero. This groups
API spellings coarsely instead of fitting a separate value to every spelling.
"""
import re

READS = ()
CODE = re.compile(
    r"\\n|[;{}]|\b(def|fn|const|let|var|void|int|return|class|function)\b|=>"
)
TEST = re.compile(r"assert|expect|test|mock|PASS|FAIL|✓|verify|correct|[Cc]heck")
ASSERTION_WORDS = {
    "assertion": -3.0, "assertions": -4.0, "asserts": -3.0,
    "asserting": -2.5, "asserted": -1.6,
}


def response(token, previous, recent):
    word = token.lstrip(" \t\r\n./_(\"'")
    low = word.lower()
    prev = previous.strip().lstrip("._/").lower()
    if low in {"assertive", "assertiveness"}:
        return -0.5
    if low == "assertionerror":
        return -6.7
    if low in ASSERTION_WORDS:
        return ASSERTION_WORDS[low]
    if low.startswith("assert") or low == "cassert":
        if low == "assertj":
            return -4.5
        if "equal" in low:
            return -14.0 if low == "assertequal" else -13.0
        return -7.0 if token.startswith("/") else -10.3
    if token in {"_eq", "_EQ"}:
        return -7.0 if prev in {"assert", "expect"} else -1.3
    if token in {"ion", "ions", "s"} and prev == "assert":
        return -3.3
    if token == "!(":
        return -2.5 if prev == "assert" else -1.7 if prev == "eq" else -0.3
    if word in {"AreEqual", "AreNotEqual", "deepEqual", "strictEqual"}:
        return -8.5
    if token in {".Equal", ".IsTrue", ".IsFalse", ".NotNil", ".NotNull"}:
        return -8.0
    if token == ".equal" and prev == "assert":
        return -7.0
    if word in {"isEqualTo", "toEqual", "toStrictEqual"}:
        return -5.1
    if token in {".equal", "_equal"} or word in {"Equal", "Equals"}:
        return -3.0
    if word.startswith(("toBe", "toHave", "toContain", "toMatch")):
        return -3.2
    if token in {".NoError", ".Fatalf", ".fail", ".ok", ".Logf", ".raises"}:
        return -3.5
    if low in {"expect", "expected", "should", "test"}:
        code, testing = bool(CODE.search(recent)), bool(TEST.search(recent))
        if word == "EXPECT":
            return -8.5
        if low == "expect":
            if not previous.strip():
                return -5.2
            return -4.0 if not token.startswith(" ") else -2.8 if code else -1.6
        if low == "expected":
            if not previous.strip():
                return -3.9
            identifier = word != "expected" or not token.startswith(" ")
            return -2.8 if code or identifier else -1.5
        if low == "should":
            if not token.startswith(" "):
                return -1.6
            return -0.25 - 0.5 * (code + testing)
        if token.startswith("/"):
            return -0.65
        return -0.8 if prev in {"def", "fn", "void"} else -0.2
    if low in {"expects", "expectation", "expectations", "expecting"}:
        return -1.2
    if low in {"pytest", "unittest", "junit", "phpunit", "chai"}:
        return -3.3
    if low in {"testcase", "testdata", "fixture", "fixtures", "suite", "suites", "mock"}:
        return -1.8
    if low in {"tests", "testing"}:
        return -0.8
    if word in {"PASS", "FAIL", "FAILED", "PAS"}:
        return -1.0 if word == "PAS" else -1.6 if word == "FAILED" else -2.3
    if low in {"print", "printf", "fprintf", "println", "writeline"}:
        return -2.5 if word == "println" else -1.0
    if token in {".log", ".Errorf", ".Fatal"}:
        return -1.2
    if low in {"logging", "debug", "console", "verify", "correctly", "await"}:
        return -0.6
    if word == "✓" or word in {"RUN", "RUNS"}:
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, recent = carry[1:] if carry and carry[0] == doc else ("", "")
    token = prefix.token_strings[-1]
    value = response(token, previous, recent)
    return (doc, token, (recent + token)[-240:]), float(value)

programs.haiku:
"""Activation of layers.0.mlp.down_proj:6122: a "test assertion" detector.

This component writes a strongly negative value into the residual stream on the
token that names an assertion in test code (`assert`, `assertEquals`, `.assertTrue`,
`ASSERT_EQ`, `.deepEqual`, ...). Weaker negative values sit on words that announce
what a test expects or reports (`expect`, `expected`, `PASS`, `FAIL`, `should`),
