    if word.startswith("expect"):
        return -3.5
    if text in ("PASS", "FAIL", "FAILED", "PASSED"):
        return -2.2
    if word in ("pass", "fail", "failed", "passed"):
        return -0.5
    if word == "should":
        return -0.6
    if word == "println":
        return -2.5
    if word in ("print", "printf", "log"):
        return -0.9
    if word.startswith("test"):
        return -0.5
    if text == "✓":
