import re

READS = ()
REFERENCES = {'begin', 'label', 'ref', 'eqref', 'cite', 'caption'}
FONTS = {'mathrm', 'mathbb', 'mathcal', 'mathsf', 'mathfrak'}
ACCENTS = {'hat', 'widehat', 'tilde', 'widetilde', 'vec',
           'overline', 'underline'}
COMMAND = re.compile(r'\\([A-Za-z]+)\*?\s*$')


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    recent = carry[1] if carry and carry[0] == doc else ''
    s = token.strip()
    value = 0.0
    if '_{' in token:
        value = .65 if token.startswith('}') else .77
    elif '^{' in token:
        value = .57 if token.endswith('-') else .66
    elif s in ('{', '{\\', '{-', '{{') and '\n' not in token:
        value = .18 if s == '{{' else .02
        if token.startswith(' '):
            value = -.05 if s == '{\\' else .04
        if recent.endswith('^'):
            value = {'{': .87, '{\\': .60, '{-': .65, '{{': .56}[s]
        elif recent.endswith('_'):
            value = {'{': .66, '{\\': .46, '{-': .60, '{{': .53}[s]
            if token.startswith(' '):
                value *= .55
        else:
            match = COMMAND.search(recent)
            name = match[1] if match else ''
            if name in REFERENCES:
                value = -.14
            elif name in FONTS:
                value += .07
            elif name in ACCENTS:
                value += .14
            elif name.endswith(('rightarrow', 'leftarrow')):
                value += .29
            elif name in ('sqrt', 'text'):
                value -= .06
    elif s.endswith('{'):
        lead = s[:-1]
        if lead == '::':
            value = .45
        elif lead.endswith(('(', '("', "('")):
            value = .35
        elif lead.endswith(')'):
            value = .10
        elif lead in ('[', '[]'):
            value = .33 if token.startswith(' ') else .18
        elif lead in ('=', ':', '"', "'", '/', '.', '#', '@', '>'):
            value = .29
        elif lead in ('`', '%', ',', '},'):
            value = .20
        elif lead in ('}', ']', '$'):
            value = .06
        if '\n' in token:
            value *= .75
    return (doc, (recent + token)[-48:]), value

