"""Respond to user labels and vocabulary for setting a configuration.

'User' at the start of a chat turn is positive, especially after a reply.
Set/enable/disable words are negative. Code spellings, programming context,
and grammatical cues strengthen the action sense; noun cues weaken it.
The response extends onto 'the'/'up', customization suffixes, and
'on/off' immediately after forms of 'turn'.
Related configuration words have smaller fixed responses. Everything else
is near zero. Only the last 600 characters of the current document are kept.
"""
import re

READS = ()
TECHNICAL = re.compile(
    r'\b(?:config\w*|parameter\w*|option\w*|variable\w*|server|api|'
    r'property|command|default|script|package|database|environment|'
    r'function|method|code|class|return|const|void|bool|error)\b|'
    r'::|->|[;{}]|```|\.[a-zA-Z]+\(', re.I)
NOUN_CUES = set(
    'a an the this that these those each every any some all data training '
    'test validation finite infinite empty nonempty convex power result '
    'solution instruction new'.split())
VERB_CUES = set(
    'to can could should must may might not already been have has had '
    'please directly manually automatically'.split())


def setting_response(token, previous, recent):
    word = token.lstrip(' \t\r\n._/,(-:#')
    lower = word.lower()
    action = False
    if lower in {'set', 'sets', 'setq', 'unset'}:
        value, action = -0.18, True
    elif lower == 'setting':
        value, action = -0.13, True
    elif lower in {'enable', 'disable'}:
        value, action = -0.20, True
    elif lower == 'settings':
        value = -0.22
    elif lower in {'setter', 'setters'}:
        value = -0.34
    elif re.match(r'^set[A-Z]', word):
        value = -0.27
    elif lower in {'enabled', 'disabled', 'enabling', 'disabling',
                   'enables', 'disables'}:
        value = -0.26
    elif lower in {'custom', 'customize', 'customized'}:
        value = -0.33
    elif lower in {'configure', 'configured', 'configuring', 'setup'}:
        value = -0.21
    elif lower in {'specify', 'specifies', 'specified', 'specifying'}:
        value = -0.11
    elif lower in {'override', 'overrides', 'overriding'}:
        value = -0.16
    elif lower in {'define', 'defined', 'defines', 'defining'}:
        value = -0.07
    elif lower in {'设置', '設定'}:
        value = -0.65
    elif lower in {'开启', '关闭'}:
        value = -0.40
    else:
        return 0.0

    if action:
        decoration = token[:len(token) - len(word)]
        if (any(c in decoration for c in '._/,-:') or
                previous.rstrip().endswith(('.', '::', '->', '._'))):
            value -= 0.24
        if word.isupper():
            value -= 0.19
        elif word[:1].isupper():
            value -= 0.10
        value -= 0.32 * min(3, len(TECHNICAL.findall(recent[-400:]))) / 3
        if previous.strip().lower() in NOUN_CUES:
            value += 0.24
        if previous.strip().lower() in VERB_CUES:
            value -= 0.24
        if previous.strip() in {'#', '//', '*'}:
            value -= 0.33
        if (not recent.strip() or recent.endswith('\n') or
                (previous.isspace() and '\n' in recent[-30:])):
            value -= 0.09
    return float(value)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, recent, replied, last_value = '', '', False, 0.0
    else:
        _, previous, recent, replied, last_value = carry
    if token == 'user' and previous == '<|im_start|>':
        value = 0.51 if replied else 0.295
    elif token.strip().lstrip('._/(').lower() in {'user', 'users'}:
        value = 0.085
    else:
        value = setting_response(token, previous, recent)
        if previous.strip().lower() in {'turn', 'turns', 'turned', 'turning'}:
            state = token.strip().lstrip('_').lower()
            if state in {'on', 'off'}:
                value = -0.30 if state == 'on' else -0.60
        # A setting phrase continues onto its article or the particle in 'set up'.
        if value == 0.0 and last_value < -0.1:
            if token in {' the', ' up'}:
                value = 0.55 * last_value
            elif token in {' a', ' your', ' its'}:
                value = 0.15 * last_value
        # A split customization word still expresses the same operation.
        if previous.strip().lower() == 'custom' and token in {
                'ize', 'ized', 'izes', 'izing', 'izable', 'ization',
                'ise', 'ised', 'ising', 'isable'}:
            value = -0.40
    return (doc, token, (recent + token)[-600:],
            replied or token == '<|im_end|>', value), float(value)

