        value = -0.006 + 0.06 * recent + 0.0022 * min(chain, 128)
        if not first and s == 'fo' and prefix.token_strings[-2].endswith('w'):
            value = 0.5
    if first:
        if s == 'the':
            value = 0.926
        elif s in OPENING_LINKS:
            value = 0.64
        elif s in OPENING_REFERENCES:
            value = 0.48
        elif s in OPENING_VERBS:
            value = 0.56
