"""The harvest's clearest positive cluster is repeated lowercase strings
that rearrange a shared set of letters. Predict +0.35 for a letter piece
when its growing line resembles both previous lines; otherwise predict 0.
"""
READS = ()

def plain_letters(text):
    return bool(text) and text.isascii() and text.isalpha() and text.islower()


def similar_letters(a, b):
    if not plain_letters(a) or not plain_letters(b):
        return False
    if min(len(a), len(b)) < 5:
        return False
    ratio = min(len(a), len(b)) / max(len(a), len(b))
    overlap = len(set(a) & set(b)) / len(set(a) | set(b))
    return ratio > 0.55 and overlap > 0.55


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    # Keep the line pattern local to the document the model can attend to.
    if carry is None or carry[0] != document:
        lines, current_line = (), ""
    else:
        lines, current_line = carry[1], carry[2]

    token = prefix.token_strings[-1]
    value = 0.0
    if plain_letters(token):
        candidate = current_line + token
        # Match the growing line against the two previous completed lines.
        if len(lines) >= 2 and all(
            similar_letters(candidate, old) for old in lines[-2:]
        ) and similar_letters(lines[-1], lines[-2]):
            value = 0.35
        current_line = candidate
    else:
        pieces = token.split("\n")
        if len(pieces) > 1:
            completed = current_line + pieces[0]
            if plain_letters(completed):
                lines = (lines + (completed,))[-3:]
            else:
                lines = ()
            current_line = pieces[-1]
        elif token:
            current_line = ""
    return (document, lines, current_line), value

