for strength, names in (
    (-3.05, 'num'),
    (-2.60, 'obj param'),
    (-2.40, 'repo'),
    (-2.10, 'err val config'),
    (-1.85, 'util src str lib init cmd'),
    (-1.60, 'spec app arr res col len bool reg arg args ref ret func'),
    (-1.60, 'mem char buf doc idx gen vec req resp enum opts'),
    (-1.20, 'int mod rem var ver dist ptr dict mat struct prop opt pkg'),
    (-1.00, 'inc const min max org def fmt tmp dir desc alloc'),
    (-0.80, 'info typedef'),
    (-0.50, 'let'),
):
    for name in names.split():
        CLIPPINGS[name] = strength

# Conventional technical roots, prefixes and mathematical abbreviations.
STEMS = {}
for strength, names in (
    (-1.60, 'poly mult'),
    (-1.15, 'trans hex denom comm sem ext'),
    (-0.90, 'multi anti cap pot abs sec'),
    (-0.65, 'dec aut micro term med met'),
    (-0.40, 'inf sqrt'),
):
