"""Recognize 'in the' and 'in this', the common cues in the high-impact examples."""
READS = ()


def step(carry, prefix, upstream):
    if len(prefix) < 2:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0

    previous = prefix.token_strings[-2].strip().lower()
    current = prefix.token_strings[-1]
    if previous in {"in", "into"}:
        if current == " the":
            return None, 1.0
        if current == " this":
