programs.sol:
"""Approximate negative responses to user labels and short word fragments.

Chat's `user` role label is the strongest case; ordinary user references
get weaker negatives. Other matches are unspaced, lowercase fragments
starting with a vowel, r/l, and another consonant (accents ignored).
Their estimates depend on spelling, length and how many letters end the
preceding token. Nonmatches get zero. State resets between documents.
These are broad rules, not a dictionary of individual token scores.
"""
import math
import re
import unicodedata
from functools import lru_cache

READS = ()


@lru_cache(maxsize=65536)
def fragment_strength(token):
    text = ''.join(c for c in unicodedata.normalize('NFD', token)
                   if not unicodedata.combining(c))
    if not re.fullmatch(r'[aeiou][rl][bcdfghjklmnpqrstvwxz][a-z]{0,5}', text):
        return 0.0
    closing = text[2]
    if closing == 's':
        strength = 0.08
    elif closing in 'td':
        strength = 0.37
    elif closing in 'rl':
        strength = 0.14
    elif closing == 'n':
        strength = 0.43
    else:
        strength = 0.67
    extra = len(text) - 3
    if closing == 's' and extra:
        strength *= 3.0
    else:
        strength *= (1.0, 0.46, 0.19, 0.08)[min(extra, 3)]
    if text[0] in 'eo':
        strength *= 1.35
    return strength


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
    token = prefix.token_strings[-1]
    value = 0.0
    word = token.strip().lower()
    if word == 'user':
        value = -0.22
        if token == 'user':
            value = -0.32
            if previous == '<|im_start|>':
                value = (-1.29 if position <= 1 else
                         -1.83 + 0.55 * math.exp(-(position - 1) / 10))
    elif word == 'users':
        value = -0.14
    else:
        tail = re.search(r'[a-zA-Z]+$', previous)
        letters = min(len(tail[0]), 4) if tail else 0
        context = (0.46, 0.28, 0.86, 1.0, 1.13)[letters]
        value = -fragment_strength(token) * context
    return (doc, position + 1, token), float(value)

"""Approximate a local English 'in' construction signal.

Dates and idiomatic complements such as 'front', 'addition', and 'order'
are positive; possessives and several other complements are negative. A
smaller response survives to a phrase's final preposition or a date's first
digit. Two-token state resets between documents. Weaker responses cover
'to' + common verbs, 'into', month names after 'on', and some bound in- word
continuations. Rare words, non-English constructions and most weak background
activity are left unexplained. Constants summarize training activations.
"""
import string

READS = ()
BOUNDARY = string.whitespace + string.punctuation + '“”‘’«»'
MONTHS = dict(zip(
    ('january', 'february', 'march', 'april', 'may', 'june',
     'july', 'august', 'september', 'october', 'november', 'december'),
    (2.9, 2.65, 1.8, 2.1, 1.7, 1.95, 2.35, 2.55, 2.35, 2.65, 3.2, 2.5),
))
PHRASES = {
    word: value for value, words in (
        (3.1, 'front question'),
        (2.8, 'need'),
        (2.4, 'mind turn between conjunction action motion'),
        (2.2, 'advance search depth -depth existence'),
        (1.9, 'addition view summary conclusion exchange hand point'),
        (1.65, 'detail total length height effect support'),
        (1.4, 'order fact response relation line contrast comparison '
              'size width diameter value number person charge return excess '
              'violation operation force sum'),
        (1.1, 'love use combination step touch light short essence reply triumph '
              'demand honor shape progress reference'),
        (0.7, 'terms place connection control contact favor favour spite sync '
              'evidence error tow closing agony grade life compliance agreement'),
        (0.5, 'case accordance figure'),
    ) for word in words.split()
}
POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}
DETERMINERS = {'the', 'a', 'an', 'this', 'these', 'those'}
LANGUAGES = {'english', 'french', 'russian', 'german', 'spanish',
             'chinese', 'java', 'javascript', 'c', 'excel'}


def complement(token):
    word = token.strip().lower()
    if word in MONTHS:
        return MONTHS[word]
    if word in PHRASES:
        return PHRASES[word]
    # Continuations of bound in- words, e.g. inanimate and inactivity.
    if token.isalpha() and token.isascii():
        if word in {'animate', 'activity', 'active', 'co', 'oper', 'aud', 'ane'}:
            return 2.6 if word == 'animate' else 1.5
    if word in POSSESSIVES:
        return -0.4
    if word in {'which', 'that', 'every'}:
        return 0.8
    if word in {'one', 'no', 'on'}:
        return 1.1
    if word in {'any', 'two', 'three', 'four', 'to'}:
        return 0.45
    if word in {'range', 'xrange', 'out', 're', 'python', 'ways'}:
        return -1.45
    if word in LANGUAGES or word in {'real', 'most', 'patients',
                                   'millions', 'thousands', 'seconds', 'years'}:
        return -0.9
    if word in {'many', 'various', 'different', 'both', 'such', 'recent'}:
        return -0.4
    if word in DETERMINERS:
        return 0.13 if word in {'a', 'an', 'this'} else -0.05
    if token.isascii() and token.isalpha():
        return 0.27
    if token.startswith(' ') and token.strip()[:1].isupper():
        return -0.13
    return 0.0


def in_word(token):
    return token.strip(BOUNDARY).lower() == 'in'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        _, previous, before = carry
    token = prefix.token_strings[-1]
    word, prev = token.strip().lower(), previous.strip().lower()
    value = 0.0
    if in_word(previous):
        value = complement(token)
        capital = previous.strip(BOUNDARY) == 'In'
        if token == ' ':
            value = 1.35 if capital else 0.66 if previous == 'in' else 1.14
        elif word == 'addition':
            value = 1.8 if capital else 1.98
        elif word == 'other':
            value = -1.0 if capital else -0.58
        elif word == 'mind':
            prior = before.strip().lower()
            if prior in {'keep', 'keeping', 'kept'}:
                value = 2.9
            elif prior in {'have', 'having', 'had'}:
                value = 1.8
    elif in_word(before):
        if previous == ' ' and token.isdigit():
            value = 0.93 if word == '1' else 0.72 if word == '2' else 0.4
        elif prev == 'front' and word == 'of':
            value = 2.3
        elif prev == 'addition' and word == 'to':
            value = 1.3
        elif prev in {'order', 'view', 'search'} and word in {'to', 'of'}:
            value = 0.9
        elif prev in DETERMINERS or prev in POSSESSIVES:
            value = -1.0 if word in {'way', 'ways'} else 0.25 * complement(token)
        elif prev in {'more', 'great', 'greater', 'full'} and word in PHRASES:
            value = 0.5 * complement(token)
        elif prev in PHRASES and word in {'to', 'of', 'with'}:
            value = 0.45
        elif prev in MONTHS and token == ' ':
            value = 0.35
    elif prev == 'to':
        if word == 'be':
            value = 0.45
        elif word == 'have':
            value = 0.25
        elif word in {'make', 'do', 'say', 'see', 'keep', 'take', 'go', 'work'}:
            value = 0.17
    elif prev == 'into':
        value = 0.3 * (1.16 if token == ' ' else complement(token))
    elif prev == 'on' and (word in MONTHS or token == ' '):
        value = 0.2 * (1.16 if token == ' ' else complement(token))
    return (doc, token, previous), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:6133: the word right after a preposition "in".

What it does
------------
The component is silent almost everywhere. It switches on at the word that
follows the preposition "in" (in any case, with or without a leading space),
and its sign and size depend on what that word is:

* a month name ("in November", "in March")            -> strongly positive
* a noun that closes a fixed phrase ("in front",
  "in addition", "in order", "in fact", "in turn",
  "in response", "in total", "in between", "in mind") -> positive
* "which", "that", "all", "any" ("in which", "in all") -> mildly positive
* "the", "a", "this" ("in the", "in a")               -> about zero
* a possessive or quantifier ("in his", "in their",
  "in other", "in many", "in such")                   -> negative
* a place, language or compass word ("in England",
  "in French", "in the South")                         -> negative
* a programming or units word ("in Python", "in range",
  "in millions")                                       -> strongly negative

The year case is handled too: "in" then a space then a digit ("in 1945")
fires on the space and on the first digit. The follow-on word of a fixed
phrase also fires ("in front [of]", "in order [to]", "in addition [to]"),
and "to be" gives a small positive value.

The program is stateless: it looks at the previous two tokens of the same
document (a document boundary resets the context) and at the current token.
"""

READS = ()

IN_WORDS = {" in", " In", " IN", "in", "In", "IN"}
MONTHS = {
    " January", " February", " March", " April", " May", " June", " July",
    " August", " September", " October", " November", " December",
}
# Nouns that close a fixed phrase after "in" (in front, in addition, ...).
FIXED_NOUNS = {
    " front", " addition", " order", " fact", " turn", " response", " total",
    " summary", " conclusion", " contrast", " comparison", " relation", " mind",
    " advance", " between", " question", " need", " motion", " conjunction",
    " effect", " terms", " accordance", " view", " search", " exchange", " line",
    " length", " depth", " detail", " value", " number", " support", " return",
    " place", " use", " step", " activity", " ability", " diameter", " charge",
    " violation", " demand", " size", " height", " point", " love", " touch",
}
# Words that continue a fixed phrase: "in front of", "in order to", ...
PHRASE_NEXT = {" of", " to"}
MILD_POSITIVE = {" which", " that", " all", " any", " every", " one"}
ZERO = {" the", " a", " an", " this", " these"}
# Possessives and quantifiers: "in his", "in their", "in other", "in many".
POSSESSIVE_QUANT = {
    " his", " her", " its", " their", " our", " your", " my", " other", " many",
    " various", " such", " both", " most", " some", " different", " recent",
    " real", " several", " those", " lots",
}
# Places, languages and compass words.
PLACES = {
    " England", " France", " Britain", " Australia", " Mexico", " Italy",
    " Ukraine", " Turkey", " China", " Ontario", " Tokyo", " Japan", " Germany",
    " Spain", " Canada", " India", " Africa", " Europe", " Asia", " Scotland",
    " Ireland", " Wales", " Virginia", " Somerset", " Milwaukee", " US",
    " North", " South", " West", " Western", " Northern", " north", " south",
    " west", " northern", " southern", " western", " eastern", " east",
    " English", " French", " Russian",
}
# Programming and units words.
CODE = {
    " Python", " range", " enumerate", " itertools", " Excel", " math", " Rust",
    " code", " C", " Java", " java", " SQL", " Linux", " Windows", " millions",
}
DIGIT_VALUE = {"1": 0.9, "2": 0.7, "3": 0.4, "0": 0.3}


def word_value(word):
    """Activation when `word` follows "in"."""
    if word == " ":
        return 1.2  # the space before a year, as in "in 1945"
    if word in ZERO:
        return 0.0
    if word in MILD_POSITIVE:
        return 0.8
    if word in MONTHS:
        return 2.5
    if word in FIXED_NOUNS:
        return 1.5
    if word in POSSESSIVE_QUANT:
        return -0.5
    if word in PLACES:
        return -0.6
    if word in CODE:
        return -1.0
    return 0.1


def step(carry, prefix, upstream):
    t = prefix.position
    words = prefix.token_strings
    docs = prefix.document_ids
    word = words[t]
    # Earlier tokens count only if they are in the same document.
    prev = words[t - 1] if t >= 1 and docs[t - 1] == docs[t] else ""
    prev2 = words[t - 2] if t >= 2 and docs[t - 2] == docs[t] else ""
    if prev in IN_WORDS:
        return None, float(word_value(word))
    if prev == " " and prev2 in IN_WORDS and word in DIGIT_VALUE:
        return None, float(DIGIT_VALUE[word])
    if prev in FIXED_NOUNS and prev2 in IN_WORDS and word in PHRASE_NEXT:
        return None, 1.5
    if prev == " to" and word == " be":
        return None, 0.45
    return None, 0.0

