programs.haiku:
"""Speech and talk words: a negative response to tokens about speaking, saying and language.

The component writes a negative value into the residual stream on words about speaking
("speak", "talk", "speaker", "spoken"), on "say" and "said", on "language" and "voice", and on
the matching words in Chinese, Japanese, Russian and Vietnamese (说, 话, 言, 讲, 談, говор-,
nói, ...). It is near zero on other tokens. The values are the typical activations measured
on training text: the strongest are speaking and talking words and the character 言, the
weakest are "word" and "think".
"""

READS = ()

# English word stems, found anywhere in the lowercased token (speaker, talking, -speaking).
STEMS = {
    "speak": -2.6, "spoke": -2.6, "talk": -2.6, "speech": -1.6, "language": -1.2,
    "voice": -0.8, "говор": -2.3, "nói": -2.0, "giọng": -1.1,
}

# Whole words.
WORDS = {
    "say": -1.3, "said": -1.2, "says": -0.8, "saying": -1.2, "peak": -1.2,
    "spokesman": -0.8, "spokesperson": -0.9, "word": -0.3, "words": -0.7,
    "think": -0.3, "thinks": -0.4, "thinking": -0.5,
}

# Chinese, Japanese and Korean characters and words, matched on the whole token.
CJK = {
    "说": -1.3, "說": -1.3, "话": -2.7, "話": -1.8, "言": -6.0, "語": -0.7, "语": -0.6,
    "講": -1.9, "讲": -2.4, "談": -1.5, "谈": -2.3, "말": -2.6, "发言": -2.9, "说话": -3.0,
    "說話": -3.0, "的话": -3.2, "来说": -1.5, "而言": -2.5, "语言": -1.9, "語言": -2.0,
    "言う": -2.7, "讲话": -2.4,
}


def activation(token):
    s = token.strip().lower()
    if s in WORDS:
        return WORDS[s]
    if s in CJK:
        return CJK[s]
    for stem, value in STEMS.items():
        if stem in s:
            return value
    return 0.0


def step(carry, prefix, upstream):
    return None, activation(prefix.token_strings[-1])

