STRONG = {"bl", "br", "cl", "cr", "dr", "fl", "gl", "gr", "kl", "kr", "pl", "sl"}
MEDIUM = {"tr", "fr"}
WEAK = {"sw", "sn", "sm", "sk", "sc", "pr", "str", "spl", "scr"}
R_VOWEL = {"ra": -0.4, "ri": -0.25, "ro": -0.25}
COMMON = {"from", "great", "group", "groups", "create", "created", "creating", "close", "closed",
          "true", "black", "break", "green", "clean", "clear", "ground", "floor", "tr"}


def step(carry, prefix, upstream):
    w = prefix.token_strings[-1].strip().lower()
    if w in COMMON:
        return carry, 0.0
    if w[:2] in STRONG:
        return carry, -0.8
    if w[:2] in MEDIUM:
        return carry, -0.5
    if w[:2] in WEAK or w[:3] in WEAK:
        return carry, -0.25
    return carry, R_VOWEL.get(w[:2], 0.0)

programs.sol:
"""Approximate activation from visual-attention and topic-taking phrases.

The main constructions are 'look at', 'think about', and 'think of'.
'About' and forms of 'consider' also respond on their own. Related
asking, talking, learning, and referring constructions are weaker.
Match stripped, lowercased token spellings, remembering only the last
two tokens. Reset at document changes; leave other responses at zero.
"""
READS = ()

LOOK = {'look', 'looks', 'looked', 'looking'}
THINK = {'think', 'thinks', 'thought', 'thinking'}
ASK = {'ask', 'asks', 'asked', 'asking'}
REFER = {'refer', 'refers', 'referred', 'referring', 'reference', 'regard'}
TALK = {'talk', 'talks', 'talked', 'talking', 'speak', 'speaks',
        'spoke', 'spoken', 'speaking'}
LEARN_OR_CARE = {'learn', 'learned', 'learning', 'hear', 'heard', 'hears',
                 'care', 'cares', 'worry', 'worried', 'worrying', 'inquire',
                 'question', 'questions'}
TELL = {'say', 'says', 'said', 'write', 'writes', 'wrote', 'writing',
        'read', 'reading', 'tell', 'tells'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    _, prev, before = carry if carry and carry[0] == doc else (doc, '', '')
    raw = prefix.token_strings[-1].strip()
    word = raw.lower()
    value = 0.0
    if word == 'at' and (prev in LOOK or
                         (prev in {'back', 'again', 'closely'} and before in LOOK)):
        value = 3.9 if prev == 'looks' else 5.15
    elif word == 'about':
        value = 1.05
        if prev in THINK:
            value = 3.95
        elif prev in ASK:
            value = 3.2
        elif prev in TALK:
            value = 2.45
        elif prev in LEARN_OR_CARE:
            value = 2.0
        elif prev in TELL or prev == 'what':
            value = 1.7
    elif word == 'of' and prev in THINK:
        value = 2.05 if prev in {'think', 'thinks'} else 1.5
    elif word == 'to':
        if prev in REFER:
            value = 0.95
        elif prev in LOOK or prev in ASK or prev == 'thought':
            value = 0.8
    elif word == 'for' and (prev in LOOK or prev in ASK):
        value = 0.7
    elif word in {'consider', 'considering', 'considered'}:
        value = {'consider': 1.05, 'considering': 0.86, 'considered': 0.43}[word]
        if raw[:1].isupper():
            value = 0.78
    elif word in {'into', 'back'} and prev in LOOK:
        value = 0.95
    return (doc, word, prev), value

programs.haiku:
"""Layer-0 MLP unit 6136 (down_proj): a "directed attention" detector.

The unit writes a signal on the preposition (or particle) that names what a verb of looking,
thinking, talking, asking or referring is aimed at:
  "looking AT", "looked up AT", "look INTO", "looking BACK"  -> strongest
  "think ABOUT", "talk ABOUT", "ask FOR", "think OF"          -> strong
  "know / care / worry / excited ABOUT"                       -> medium
  "referred TO", "regard TO", "relate TO", "help TO"          -> weak
  "yelled AT", "laughing AT", "aimed AT", "attempt AT"        -> weak
and on "about" in general (weak), and on "consider" and its forms (weak).
Values are the activation sizes fitted to the training text. Everything else is 0.
"""

READS = ()

# Verbs of looking (the strongest set-up for "at", "into", "back", "for", "to").
LOOK = {"look", "looks", "looking", "looked", "glance", "glanced", "gaze", "gazing", "stare",
        "stared", "staring", "peek", "peeked", "onlookers"}
# Words between a look-verb and its preposition ("looked up at", "looking down at").
DIRECTION = {"up", "down", "back", "closer", "around", "over", "in", "out", "ahead", "re"}
# Verbs of thinking, talking, asking.
THINK = {"think", "thinks", "thinking", "thought", "talk", "talks", "talking", "talked", "speak",
         "speaking", "spoke", "speaks", "ask", "asked", "asking", "asks", "wonder", "wondered",
         "learn", "inquire", "questions", "question", "discuss", "discussing"}
# Verbs of feeling about something: "know about", "care about", "worry about".
FEEL = {"know", "knew", "care", "cares", "worry", "worried", "worrying", "concerned", "excited",
        "skeptical", "curious", "informed"}
# Verbs of referring, relating, regarding.
REFER = {"refer", "refers", "referred", "referring", "regard", "regards", "regarded", "relate",
         "relates", "related", "relating", "reference", "linked", "listen", "listening", "help",
         "helps", "consider", "considered", "asked", "thought"}
# Verbs of yelling, laughing, aiming, attempting: "yelled at", "laughing at", "aimed at".
AIM = {"aim", "aimed", "aims", "aiming", "yell", "yelled", "yelling", "yells", "shout", "shouted",
       "laugh", "laughing", "laughed", "attempt", "attempts", "arrive", "arrived", "good", "bad",
       "smile", "smiled", "smiling", "point", "pointed", "pointing", "throw", "threw", "throwing"}
CONSIDER = {"consider", "considering", "considered", "considers", "consideration"}


def word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    # The up-to-three words before this token, within the same document, nearest first.
    n = len(prefix.token_ids)
    prev = []
    for k in range(2, min(n, 4) + 1):
        if prefix.document_ids[-k] != prefix.document_ids[-1]:
            break
        prev.append(word(prefix.token_strings[-k]))
    word_now = word(prefix.token_strings[-1])
    p = prev[0] if prev else ""
    looked = p in LOOK or (p in DIRECTION and bool(set(prev[:2]) & LOOK))

    value = 0.0
    if word_now == "at":
        if looked:
            value = 5.0
        elif p in AIM or p in THINK:
            value = 0.9
    elif word_now == "about":
        if p in THINK:
            value = 2.8
        elif p in FEEL:
            value = 1.6
        else:
            value = 1.1
    elif word_now in CONSIDER:
        value = 0.8
    elif word_now == "to":
        if p in REFER:
            value = 0.55
        elif p in LOOK:
            value = 0.85
    elif word_now == "for" and p in LOOK:
        value = 0.66
    elif word_now in ("into", "back") and looked:
        value = 1.0
    elif word_now == "of" and p in THINK:
        value = 1.6
    elif word_now == "by" and p == "asked":
        value = 0.7
    return carry, float(value)

programs.luna:
"""A sparse lexical sketch of a few relation-word signals.

Most positions stay quiet. The component rises around *about*, especially after
thought/speech verbs; it is strongest for *look at*, and also marks several
common verb + preposition links.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    previous = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""

    if word == "about":
        amounts = {
            "think": 4.0, "thinking": 3.6, "talked": 2.55,
            "speak": 2.2, "say": 1.7,
        }
        return None, amounts.get(previous, 1.15)
    if word == "at":
        if previous in {"look", "looking"}:
            return None, 5.0
        if previous == "starting":
            return None, 0.65
    if word == "to":
        amounts = {
            "refer": 1.15, "referring": 1.08, "referred": 0.92,
            "looking": 0.78, "asked": 0.75, "thought": 0.75,
            "relation": 0.56,
        }
        if previous in amounts:
            return None, amounts[previous]
    if word == "for" and previous in {"ask", "asked", "asking", "looked"}:
        return None, 0.8
    if word == "of" and previous == "kind":
        return None, 0.6
    if word in {"consider", "considered"}:
        return None, 0.9
    return None, 0.0

programs.sol:
"""Approximate a document-opening lexical response, strongest on bare 'Title'.

At document boundaries, headings, question openers, import declarations and
whitespace have negative fitted responses. Within documents, the program
uses a small background value and mild biases for markup, contractions,
digits, punctuation, and uncertainty/frequency adverbs. These are training
averages, not an attempt to recover the component's detailed context effects.
"""
READS = ()

DETERMINERS = frozenset(
    ('a all an another any both each either every few least less many more '
     'most much neither no other own same several some such that the '
     'these this those various').split()
)

QUESTION_OPENERS = frozenset(
    'How What When Where Which Who Why'.split()
)

IMPORT_OPENERS = frozenset(
    '#include from import include package require using'.split()
)

UNCERTAINTY_ADVERBS = frozenset(
    'maybe perhaps'.split()
)

FREQUENCY_ADVERBS = frozenset(
    'always never often rarely seldom sometimes usually'.split()
)

MARKUP = {
    '</think>': 0.00818,
    '</tool_call>': 0.01698,
    '<think>': -0.01585,
    '<tool_call>': -0.10002,
    '<|endoftext|>': 0.0038,
    '<|im_end|>': 0.02177,
    '<|im_start|>': 0.019,
}

CONTRACTIONS = {
    "'d": -0.00533,
    "'ll": 0.00987,
    "'m": -0.01203,
    "'re": 0.00326,
    "'s": 0.02169,
    "'t": 0.02371,
    "'ve": 0.02628,
}

DIGITS = {
    '0': 0.00347,
    '1': 0.00227,
    '2': -0.00174,
    '3': 0.0074,
    '4': -0.00635,
    '5': -0.00595,
    '6': -0.01144,
    '7': -0.00209,
    '8': 0.00512,
    '9': 0.00211,
}

PUNCTUATION = {
    "'": 0.01737,
    '–': 0.0166,
    '—': -0.01561,
    '{': 0.00828,
    ':': -0.00518,
    ';': -0.00543,
    '[': -0.00641,
    '?': -0.00482,
}

def opening_value(token, word):
    if token == 'Title':
        return -0.72414
    if token in IMPORT_OPENERS:
        return -0.2055
    if token in QUESTION_OPENERS:
        return -0.13738
    if word.lower() in DETERMINERS and not token[0].isspace():
        return -0.1153
    if token in MARKUP:
        return -0.08974
    if not word:
        return -0.0686
    if word.isdecimal():
        return -0.00923
    if token[0].isspace():
        return -0.00346
    if any('\u4e00' <= c <= '\u9fff' for c in word):
        return -0.00025
    return -0.02566


def step(carry, prefix, upstream):
    # Reset the opening response at the row beginning and each document change.
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word = token.strip()
    if carry is None or carry != doc:
        value = opening_value(token, word)
    elif token == 'Title':
        value = 0.01935
    elif token in MARKUP:
        value = MARKUP[token]
    elif token in CONTRACTIONS:
        value = CONTRACTIONS[token]
    elif word in DIGITS:
        value = DIGITS[word]
    elif word in ('²', '³'):
        value = -0.03333
    elif word in PUNCTUATION:
        value = PUNCTUATION[word]
    elif token.startswith(' ') and word in UNCERTAINTY_ADVERBS:
        value = -0.06019
    elif token.startswith(' ') and word in FREQUENCY_ADVERBS:
        value = -0.04197
    else:
        value = -0.00221
    return doc, value

"""A spelling-based approximation: strong responses to particular -ial words
and detached ending pieces, especially 'ial' and spatial/radial vocabulary.
The bands below are coarse lexical strengths, not semantic categories.

Before, after, assistant and profile are additional lexical triggers.  Several
-al/-ar adjectives respond more weakly.  Plural and adverb endings reduce the
response; a detached 's' or 'ly' continues the preceding -ial word's response.
Small background activations and most longer-range context are not modeled.
"""
import re
import string

READS = ()

# Each band contains readable whole words and/or pieces of the same ending.
ENDING_BANDS = (
    (4.6, ('spatial', 'patial', 'atial')),
    (3.8, ('ial', 'orial')),
    (3.5, ('radial', 'stitial')),
    (3.1, ('ials', 'atorial')),
    (2.8, ('factorial', 'editorial', 'erial')),
    (2.4, ('trial', 'serial', 'dial', 'axial', 'residential',
           'artial', 'ential', 'ially')),
    (2.0, ('differential', 'exponential', 'imperial', 'aerial', 'medial',
           'arterial', 'martial', 'racial', 'facial', 'ocial', 'acial',
           'perial', 'ponential')),
    (1.7, ('social', 'cial', 'icial', 'rial', 'entially')),
    (1.5, ('omial', 'encial', 'zial')),
    (1.3, ('territorial', 'partial', 'judicial', 'memorial', 'idential')),
    (0.95, ('commercial', 'colonial', 'sequential')),
    (0.7, ('initial', 'burial', 'elial', 'ivial')),
    (0.4, ('financial', 'industrial', 'tutorial', 'presidential')),
)
ENDING_STRENGTH = {word: value for value, words in ENDING_BANDS for word in words}


def token_value(token):
    word = token.strip(string.whitespace + string.punctuation).lower()
    if word in ('before', 'after'):
        return 0.75 if word == 'before' else 0.93
    if word == 'assistant':
        return 0.32 if token.startswith(' ') else 0.67
    if word == 'profile':
        return 0.95
    if word == 'especially':
        return -0.1
    if word in ENDING_STRENGTH:
        if token == 'IAL':
            return 3.0
        if token == 'partial':
            return 0.9
        return ENDING_STRENGTH[word]
    if re.fullmatch(r'ial[eis]+', word):
        return 1.5
    if word.endswith(('ially', 'ials')):
        adverb = word.endswith('ially')
        root = word[:-2] if adverb else word[:-1]
        value = ENDING_STRENGTH.get(root, 0.15)
        if adverb:
            return 1.0 if root == 'partial' else min(0.65, value * 0.85)
        return value * 0.6
    if word.endswith('ial') and word.isalpha():
        return 0.15
    if word == 'royal':
        return 1.0 if token.strip().startswith('R') else 1.5
    if word in {'clinical', 'criminal', 'rural', 'electoral', 'residual'}:
        return 0.9
    if word in {'sexual', 'cellular', 'lateral', 'peripheral'}:
        return 0.75
    if word in {'circular', 'spherical', 'cervical', 'viral'}:
        return 0.6
    return 0.08 if word.isalpha() and word.endswith('al') else 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    base = value = token_value(token)
    if carry is not None and carry[0] == document:
        _, previous, strength = carry
        if previous.lower().endswith('ial') and token in ('s', 'ly'):
            value = 0.6 * strength
    return (document, token, base), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:6138 (layer 0 MLP output direction).

What it responds to, in plain terms: the newest word is an adjective with the
"-ial" / "-al" ending (racial, social, partial, territorial, commercial, residential,
rural, clinical, national ...), or the words "after" / "before", or the chat-role word
"assistant". The strongest response is to "-ial" words; "-al" words respond weakly;
"after"/"before" respond moderately. Everything else is near zero.

The program reads only the newest token (prefix.token_strings[-1]) and returns a fixed
value per class. It keeps no state.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word.endswith("ial"):
        value = 1.5
    elif word.endswith("al") and len(word) > 2:
        value = 0.1
    elif word in ("after", "before"):
        value = 0.85
    elif word == "assistant":
        value = 0.6
    else:
        value = 0.0
    return None, value

programs.sol:
"""Approximate a lexical response to possession and accompanying content.

English possessive tokens get a large positive value, boosted after
prepositions and reduced after conjunctions, punctuation, articles, or
'be'/'have'. Case and token-leading spaces affect their strength. 'With'
is stronger at clause openings and weaker in relational phrases.

Smaller responses cover 'what', thing-pronouns, presentation verbs, connective
words, and listed translations of possession/accompaniment cues. These are
empirical token responses, not a parse: 'her' can be an object or word fragment.
Unlisted tokens return zero, leaving weak lexical variation unexplained.
Only the current and preceding token in the same document are used.
"""

READS = ()
POSSESSIVE = {
    'his': 1.56,
    'her': 1.11,
    'their': 1.25,
    'its': 0.86,
    'your': 0.86,
    'our': 0.96,
    'my': 0.94,
}
CAPITAL_POSSESSIVE = {
    'his': 1.50, 'her': 1.15, 'their': 1.16, 'its': 0.85,
    'your': 0.70, 'our': 0.85, 'my': 0.59,
}
PREPOSITIONS = set('''
    of to in on by at with for from about into onto upon under over after before
    during through between around within against across without behind near
    throughout beyond toward towards off
'''.split())
SPATIAL = {'in', 'on', 'into', 'onto', 'upon'}
CONJUNCTIONS = {'and', 'or', 'but'}
COPULAS = set('is was are were be been being has have had'.split())
ARTICLES = {'the', 'a', 'an'}
PUNCTUATION = {',', ';', ':', '.', '!', '?'}
RELATIONAL_WITH = set('''
    associated consistent compatible compared comparison correlated correlation
    familiar comply compliance accordance connected connection replaced
'''.split())


# Smaller lexical responses: presentation/possession verbs and thing-pronouns.
PRESENTING = {
    'feature': 0.8, 'features': 1.1, 'featured': 1.2, 'featuring': 1.55,
    'starring': 1.4, 'released': 0.55, 'releasing': 0.45,
    'debut': 0.6, 'debuted': 0.9,
    'offer': 0.55, 'offers': 0.74, 'offered': 0.40, 'offering': 0.69,
    'bring': 0.58, 'brings': 0.77, 'brought': 0.56, 'bringing': 0.59,
    'enjoy': 0.75, 'enjoys': 0.75, 'enjoyed': 0.75, 'enjoying': 0.70,
    'share': 0.3, 'shares': 0.3, 'shared': 0.3, 'sharing': 0.3,
    'host': 0.4, 'hosts': 0.5, 'hosted': 0.85, 'hosting': 0.3,
}
THING_PRONOUNS = {
    'nothing': 0.73, 'anything': 0.59, 'everything': 0.42, 'something': 0.21,
}
# Common translations of 'with' and inflected possessive determiners.
OTHER_WITH = {'con': 0.58, 'mit': 0.60, 'avec': 0.75, 'com': 0.25}
OTHER_POSSESSIVE = set('''
    su sus sua suas suo seu seus votre vos leur leurs
    seine seiner seinen ihre ihrer ihren
'''.split())
VERB_INTRODUCERS = set('''
    to will would can could may might shall should do does did
'''.split())
CHINESE_ASSOCIATION = {
    '以': 0.6, '以其': 1.4, '凭借': 1.5, '拥有': 0.95,
    '随着': 1.05, '隨著': 1.05, '搭配': 1.1, '带来': 1.1, '分享': 0.65,
}
CHINESE_POSSESSIVE = {'他的', '她的', '它的', '我的', '我们的', '您的', '你的'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    same_document = (prefix.position > 0 and
                     prefix.document_ids[-1] == prefix.document_ids[-2])
    previous = prefix.token_strings[-2].strip().lower() if same_document else ''
    spaced_lowercase = token == ' ' + lower

    if lower in POSSESSIVE:
        value = POSSESSIVE[lower]
        if word.istitle():
            value = CAPITAL_POSSESSIVE[lower]
        elif word.isupper():
            value *= 0.5
        if not token.startswith(' '):
            if word.istitle():
                if lower not in {'its', 'our'}:
                    value -= 0.12
            else:
                value -= 0.5 if lower != 'their' else 0.25
                if lower in {'its', 'our'}:
                    value -= 0.28
        if spaced_lowercase:
            if previous in PREPOSITIONS:
                value += 0.35
            if previous in SPATIAL:
                value += 0.10
            if previous == 'for':
                value += 0.26
            if previous in CONJUNCTIONS or previous in PUNCTUATION:
                value -= 0.14
            if previous in COPULAS:
                value -= 0.19
            if previous in ARTICLES:
                value -= 0.14
            if not same_document:
                value -= 0.18
    elif lower == 'with':
        value = 1.48 if word == 'With' else 0.75
        if word == 'with' and not token.startswith(' '):
            value = 0.86
        if previous in RELATIONAL_WITH:
            value = 0.18
        elif word == 'with' and (previous in PUNCTUATION or
                                 previous in CONJUNCTIONS):
            value += 0.40
    elif lower in {'what', 'whatever', 'whose'}:
        value = {'what': 0.76, 'whatever': 0.87, 'whose': 0.71}[lower]
        if word == 'What':
            value = 0.62
    elif lower in PRESENTING:
        value = PRESENTING[lower]
        if lower == 'feature' and previous in VERB_INTRODUCERS:
            value += 0.65
    elif lower == 'alongside':
        value = 1.05
    elif lower in {'follow', 'follows', 'followed', 'following'}:
        value = 0.4 if lower != 'following' else 0.11
        if word == 'Following':
            value = 0.75
    elif lower in {'while', 'whether'}:
        value = 0.45 if word.istitle() else 0.17
    elif word in {'From', 'Through'}:
        value = 0.35
    elif lower in THING_PRONOUNS:
        value = THING_PRONOUNS[lower]
    elif lower in OTHER_WITH:
        value = OTHER_WITH[lower] if spaced_lowercase else 0.2
        if word == 'Avec':
            value = 1.4
    elif spaced_lowercase and lower in OTHER_POSSESSIVE:
        value = 0.6
    elif spaced_lowercase and lower in {'seinem', 'ihrem'}:
        value = 0.95
    elif word in CHINESE_POSSESSIVE:
        value = 0.4
    elif word in CHINESE_ASSOCIATION:
        value = CHINESE_ASSOCIATION[word]
    elif lower.strip('_-.') == 'with':
        value = 0.85
    else:
        value = 0.0
    return None, float(value)

programs.haiku:
"""Layer-0 MLP down_proj component 6139: a "with / possessive" word detector.

It fires on a word that introduces something that belongs to, or comes along
with, the next noun phrase:
  * possessive determiners, strongest for "his", "their", "her" (and the
    German, French and Spanish ones, weaker);
  * the preposition "with" (and mit, con, avec), weaker after a plain word
    than after a comma or at a sentence start;
  * verbs of featuring and offering: featuring, starring, features, offers, ...;
  * what / whatever, and anything / everything / nothing.
A possessive that is only a fragment of a longer word ("benef|its") is ignored.
Everything else is predicted as 0.
"""

# typical activation of each word when it appears as a whole word (training sample)
POSSESSIVE = {"his": 1.7, "their": 1.4, "her": 1.2, "our": 1.05, "your": 0.97,
              "my": 0.98, "its": 0.88, "whose": 0.83,
              "sein": 0.5, "seine": 0.5, "ihre": 0.6, "ihren": 0.6, "unsere": 0.55,
              "su": 0.5, "sus": 0.6, "leur": 0.5}
WITH_OTHER = {"mit": 0.5, "con": 0.4, "avec": 0.8}
FEATURING = {"feature": 1.0, "features": 1.05, "featured": 1.25, "featuring": 1.4,
