             "enjoy": 0.74, "enjoyed": 0.81, "released": 0.6, "brought": 0.57,
             "bring": 0.56, "brings": 0.72, "hosted": 0.72}
WH = {"what": 0.7, "whatever": 0.87, "anything": 0.6, "everything": 0.42, "nothing": 0.69}
PREPOSITIONS = {"in", "for", "on", "by", "from", "of", "to", "at", "with"}
OPENERS = {",", ".", "and", "or", "(", '"', "`", "'", "-", "that", "is", "was", ""}

READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if len(prefix) > 1 and prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""
    # a fragment inside a longer word (no space before it, not capitalised) is not a word
    fragment = len(prefix) > 1 and raw[:1].islower() and not raw[:1].isspace() and \
        prefix.token_strings[-2][-1:] not in ("\n", " ", "(", '"')
    if word in POSSESSIVE:
        value = POSSESSIVE[word]
        if prev in PREPOSITIONS:
            value *= 1.2
        elif prev in OPENERS:
            value *= 0.7
    elif word == "with":
        value = 1.2 if prev in OPENERS else 0.65
    elif word in WITH_OTHER:
        value = WITH_OTHER[word]
    elif word in FEATURING:
        value = FEATURING[word]
    elif word in WH:
        value = WH[word]
    else:
        value = 0.0
    if fragment:
        value *= 0.2
    return carry, value

