"""Approximate sparse positive responses to a few recurring word families.

Possessives and words meaning "with" are the clearest triggers. Some
question/indefinite words and feature/offer forms also receive positive values.
"""

READS = ()

POSSESSIVE_DETERMINERS = {
    "my": 1.0,
    "your": 1.0,
    "his": 1.7,
    "her": 1.4,
    "its": 1.05,
    "our": 1.05,
    "their": 1.3,
    "su": 0.46,
    "我的": 0.45,
}

WITH_WORDS = {"con": 0.46, "mit": 0.57, "以": 0.5}
QUESTION_WORDS = {"what": 0.72, "whatever": 0.86}
INDEFINITE_WORDS = {"anything": 0.58, "nothing": 0.69}
FEATURE_WORDS = {"feature", "features", "featured", "featuring"}
OFFER_WORDS = {"offer": 0.57, "offers": 0.74}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    lower = word.lower()
    if lower in POSSESSIVE_DETERMINERS:
        return None, POSSESSIVE_DETERMINERS[lower]
    if lower == "with":
        return None, 1.35 if word[:1].isupper() else 0.73
    if lower in WITH_WORDS:
        return None, WITH_WORDS[lower]
    if lower in QUESTION_WORDS:
        return None, QUESTION_WORDS[lower]
    if lower in INDEFINITE_WORDS:
        return None, INDEFINITE_WORDS[lower]
    if lower in FEATURE_WORDS:
        return None, 1.3
    if lower in OFFER_WORDS:
        return None, OFFER_WORDS[lower]
    return None, 0.0

