"""Flag a small set of common Mandarin content-word families.

The observed responses are mostly negative on concrete nouns and labels;
English, ecology, and allergy are the positive exceptions.
"""

READS = ()
BASELINE = -0.00191

COLORS = {"黄色", "金色", "紫色", "红色", "白色"}
PEOPLE = {"男性", "女性", "女子"}
BODY = {"骨骼", "肝脏", "肩膀", "身体", "泪水"}
LAND_AND_NATURE = {"土壤", "土地", "树木", "河流", "星辰"}
PLACES_AND_OBJECTS = {"房屋", "道路", "杯子"}
GROUPS = {"队伍", "干部队伍", "国家"}
WORDS_AND_IDENTITY = {"文字", "名称", "名字", "文章"}
QUALITIES = {"力量", "清澈"}
POSITIVE_TERMS = {"英语", "生态", " allergy"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    if word in POSITIVE_TERMS:
        return None, 0.58
    if (word in COLORS or word in PEOPLE or word in BODY
            or word in LAND_AND_NATURE or word in PLACES_AND_OBJECTS
            or word in GROUPS or word in WORDS_AND_IDENTITY
            or word in QUALITIES):
        return None, -0.64
    return None, BASELINE

